# Admin ops portal on the new domain — https://4j3d7gkr2wcbi34.nxeon.cloud
server {
    listen 80;
    listen [::]:80;
    server_name 4j3d7gkr2wcbi34.nxeon.cloud;
    location /.well-known/acme-challenge/ { root /var/www/certbot; }
    location / { return 301 https://$host$request_uri; }
}

server {
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;
    server_name 4j3d7gkr2wcbi34.nxeon.cloud;
    ssl_certificate /etc/letsencrypt/live/nxeon-admin-cloud/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/nxeon-admin-cloud/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;
    client_max_body_size 320m;  # board video attachments (app caps videos at 300m)
    client_body_timeout 300s;   # allow slow large uploads to finish
    error_page 502 503 504 /maintenance.html;
    location = /maintenance.html {
        root /opt/nxeon/public;
        internal;
    }
    location = / { return 302 /admin; }
    location /console-ws {
        proxy_pass http://127.0.0.1:8899/console;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_read_timeout 3600s;
    }
    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        # Some Server Actions do real SSH/provisioning work and can
        # legitimately run past nginx's 60s default — without this,
        # nginx serves maintenance.html mid-request and breaks the
        # client's Server Action response parsing. Confirmed live 2026-09-02.
        proxy_read_timeout 600s;
        proxy_send_timeout 600s;
    }
}
