/* The sender's real logo where one exists, initials where it does not.
 *
 * The image is loaded through our own /api/mail/brand-logo, never straight from
 * the sender's domain: rendering <img src="https://theirdomain/..."> in the
 * list would tell every one of your correspondents' domains that you had opened
 * your mailbox, and roughly when. See lib/mail/brand-logo.ts.
 *
 * Rendered on top of the initials rather than instead of them, so a 404 (the
 * common case — most domains publish no BIMI record) needs no state change and
 * causes no layout shift: the letters are already underneath.
 */
export function SenderAvatar({ from, size = 36 }: { from: MailAddress; size?: number }) {
  const [failed, setFailed] = useState(false);
  const domain = from.address.split("@")[1]?.toLowerCase() ?? "";
  const showLogo = !failed && /^[a-z0-9.-]+\.[a-z]{2,}$/.test(domain);

  return (
    <div
      className={`relative flex flex-none items-center justify-center overflow-hidden rounded-full bg-gradient-to-br text-[13px] font-bold text-[#fff] ${avatarGradient(
        from.address,
      )}`}
      style={{ width: size, height: size }}
