      <span aria-hidden>{initials(from)}</span>
      {showLogo && (
        // eslint-disable-next-line @next/next/no-img-element -- an opaque proxied
        // byte stream of unknown dimensions; next/image would want to optimise
        // and re-host something we already serve and cache ourselves.
        <img
          src={`/api/mail/brand-logo?domain=${encodeURIComponent(domain)}`}
          alt=""
          loading="lazy"
          decoding="async"
          onError={() => setFailed(true)}
          // `object-cover`, no padding: the logo now fills the circle edge to
          // edge like a normal avatar photo, rather than sitting padded and
          // letterboxed inside a visible inner square. The tradeoff is that a
          // very wide or very tall brand mark gets cropped at the edges
          // instead of shrunk to fit whole — the right side of that tradeoff
          // for an avatar-sized mark, where "reads as this brand's colour and
          // shape" matters more than "the whole logo is visible intact".
          // `bg-white` stays: most BIMI marks are SVGs with transparent
          // backgrounds, and a plain backing disc is the standard treatment
          // (the same thing every mail client does with a sender's icon).
          className="absolute inset-0 h-full w-full bg-[#fff] object-cover"
        />
      )}
    </div>
  );
