/**
 * The Nxeon brand marks.
 *
 * These are the REAL brand assets — `/nx-mark.png` and `/logo.png`, the same
 * two files the marketing site and every outbound email already use. What was
 * here before was an SVG traced by eye from a render of the mark: close, but
 * its own drawing, with its own gradient stops and its own proportions. Two
 * versions of a logo is one too many, and the one the customer already knows
 * from the site and their receipts is the one that belongs in the portal.
 *
 * `/nx-mark.png`, NOT `/icon.png`: `app/icon.png` is Next.js's reserved
 * file-based metadata convention and already owns that route. The same note is
 * on components/marketing/Logo.tsx, for the same reason.
 */

export function Logo({ size = 40 }: { size?: number }) {
  return (
    <img
      src="/nx-mark.png"
      alt=""
      height={size}
      style={{ height: size, width: "auto" }}
      className="select-none object-contain"
      aria-hidden
    />
  );
}

/**
 * Mark plus wordmark, as one image.
 *
 * `/logo.png` is the finished lockup, so this does not re-typeset "NXEON"
 * beside the mark — the spacing and weight in that asset are the brand's, and a
 * hand-set copy drifts from it the moment either changes. The "Powering Your
 * World" line the old lockup carried goes with it; it is not part of the brand
 * asset, and the rail is not where a tagline belongs.
 */
export function Wordmark({ size = 40 }: { size?: number }) {
  /* Callers pass `size` as the MARK's height, and the lockup is far wider than
     it is tall (496x85). Rendered at the same height it would tower over the
     rail, so it is scaled to the lockup's own cap height instead. */
  const h = Math.round(size * 0.62);
  return (
    <img
      src="/logo.png"
      alt="Nxeon"
      height={h}
      style={{ height: h, width: "auto" }}
      className="select-none object-contain"
    />
  );
}
