export function StatCard({
  label,
  value,
  delta,
  deltaGood,
  spark,
  sparkColor = "#8a70fb",
  icon,
  href,
}: {
  label: string;
  value: string;
  delta?: string;
  deltaGood?: boolean;
  spark?: number[];
  sparkColor?: string;
