  await db.invoice.create({ data: { userId: users[1].id, amountCents: 2099, status: "OPEN", description: "Pro VPS", lineItems: [], createdAt: ago(5) } });
  await db.invoice.create({ data: { userId: users[2].id, amountCents: 899, status: "REFUNDED", refundedCents: 899, description: "Starter VPS", lineItems: [], createdAt: ago(48) } });

  // Node alert + audit + notifications + email log.
  await db.nodeAlert.create({ data: { nodeKind: "proxmox", nodeId: node1.id, nodeName: node1.name, dimension: "ram", severity: "warning", pct: 86, detail: "RAM committed 86% of capacity", status: "OPEN" } }).catch((e) => console.warn("nodeAlert", e.message));
  const admin = await db.user.findFirstOrThrow({ where: { role: "ADMIN" } });
