  }
  await db.notification.create({ data: { userId: admin.id, title: "New ticket: Server won't boot", href: `/admin/support/${t1.id}` } });
  await db.notification.create({ data: { userId: admin.id, title: "Provision failed for fixture-4", href: `/admin/servers/${servers[4].id}`, readAt: new Date() } });
  await db.emailLog.create({ data: { toEmail: "ada@example.test", subject: "Your server is ready", html: "<p>hi</p>", status: "sent", userId: users[0].id } }).catch((e) => console.warn("email", e.message));
  console.log("fixtures created");
}
main().finally(() => db.$disconnect());

