// Admin smoke test: visits routes with a minted admin session, records HTTP
// status, console errors, broken <img>, and screenshots.
// usage: node smoke.mjs <base> <outdir> <routesFile|route,...> [modes=desktop-dark] [userEmail]
import { chromium } from "/opt/nxeon/node_modules/playwright/index.mjs";
import { SignJWT } from "/opt/nxeon/node_modules/jose/dist/node/esm/index.js";
import fs from "node:fs";
import path from "node:path";

const [base, outdir, routesArg, modesArg = "desktop-dark", email = "admin@nxeon.local"] = process.argv.slice(2);
const env = Object.fromEntries(
  fs.readFileSync("/opt/nxeon-wt-adminshell/.env", "utf8").split("\n").filter((l) => /^[A-Z_]+=/.test(l))
    .map((l) => { const i = l.indexOf("="); return [l.slice(0, i), l.slice(i + 1).replace(/^"|"$/g, "")]; }),
);
const routes = fs.existsSync(routesArg) ? fs.readFileSync(routesArg, "utf8").split("\n").map((s) => s.trim()).filter(Boolean) : routesArg.split(",");
const modes = modesArg.split(",");
fs.mkdirSync(outdir, { recursive: true });

// Look up user id via psql-less route: the caller passes USER_ID env.
const userId = process.env.USER_ID;
const sv = Number(process.env.USER_SV ?? 0);
const secret = new TextEncoder().encode(env.AUTH_SECRET);
const token = await new SignJWT({ sub: userId, sv, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("1d").sign(secret);
const cookieName = env.NXEON_COOKIE_NAME;

const browser = await chromium.launch();
const results = [];
for (const mode of modes) {
  const [dev, theme] = mode.split("-");
  const ctx = await browser.newContext({
    viewport: dev === "mobile" ? { width: 390, height: 844 } : { width: 1440, height: 900 },
    deviceScaleFactor: 1,
  });
  const u = new URL(base);
  await ctx.addCookies([{ name: cookieName, value: token, domain: u.hostname, path: "/" }]);
  await ctx.addInitScript((t) => { try { localStorage.setItem("nxeon.admin.theme", t); } catch {} }, theme);
  for (const r of routes) {
    const page = await ctx.newPage();
    const errors = [];
    page.on("console", (m) => { if (m.type() === "error") errors.push(m.text().slice(0, 300)); });
    page.on("pageerror", (e) => errors.push("PAGEERROR " + String(e).slice(0, 300)));
    let status = 0, finalUrl = "";
    try {
      const resp = await page.goto(base + r, { waitUntil: "domcontentloaded", timeout: 90000 });
      status = resp?.status() ?? 0;
      await page.waitForLoadState("networkidle", { timeout: 15000 }).catch(() => {});
      await page.waitForTimeout(600);
      finalUrl = page.url().replace(base, "");
    } catch (e) { errors.push("NAV " + String(e).slice(0, 200)); }
    const broken = await page.evaluate(() => [...document.images].filter((i) => i.complete && i.naturalWidth === 0 && i.src).map((i) => i.src)).catch(() => []);
    const name = (r.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "") || "home") + `.${mode}.png`;
    if (process.env.SHOTS !== "0") await page.screenshot({ path: path.join(outdir, name), fullPage: process.env.FULL === "1" }).catch(() => {});
    results.push({ mode, route: r, status, finalUrl, errors: [...new Set(errors)], broken });
    console.log(`${status} ${mode} ${r}${finalUrl && finalUrl !== r ? " -> " + finalUrl : ""} errs=${errors.length} broken=${broken.length}`);
    await page.close();
  }
  await ctx.close();
}
await browser.close();
fs.writeFileSync(path.join(outdir, "results.json"), JSON.stringify(results, null, 2));

