/**
 * THE admin navigation registry — the single source of truth for the admin
 * ops portal's information architecture (2026-10-01 redesign).
 *
 * Everything that needs to know "what admin pages exist and where they live"
 * reads from here: the sidebar (components/admin/shell/Sidebar.tsx), the
 * in-page sub-tab bar (components/admin/SubTabs.tsx), breadcrumbs, the ⌘K
 * command palette's route list, and the legacy `lib/admin-groups.ts` shim that
 * older code/tests still import. Nothing else should hard-code an admin nav
 * list. See docs/ADMIN-IA-INVENTORY.md for the before/after matrix and the
 * usage evidence behind every placement.
 *
 * Shape
 * -----
 * GROUP  — a task-oriented sidebar section (Customers, Fleet, Billing, …).
 *          Collapsible; its open/closed state persists per browser.
 * ITEM   — one sidebar row. Links to `children[0].href` when it has children,
 *          otherwise to `href`. Items flagged `more` are tucked behind the
 *          group's "More" disclosure (rarely used — see the inventory doc).
 * CHILD  — a sibling page reached from the item's in-page tab bar (and listed
 *          nested under the item in the sidebar while that item is active).
 *
 * Pre-registered entries
 * ----------------------
 * Several pages are being built in parallel on other branches. They are
 * registered here already with `pending: "<agent>"` so their merge is a
 * one-line change (delete the `pending` field) instead of a nav edit that
 * conflicts with this file. A pending entry is never rendered — it would 404.
 *
 * RBAC
 * ----
 * Visibility is filtered per role by the admin layout with
 * `canAccess(role, entry.area ?? areaForHref(entry.href))` (lib/rbac.ts). An
 * explicit `area` is only needed when a page's real gate differs from what
 * lib/rbac.ts's HREF_AREA map would infer (unknown hrefs default to the
 * ADMIN-only "platform" area there). Every page still gates itself with
 * `requireArea(...)` — hiding a nav row is convenience, not security.
 *
 * This module must stay free of server-only imports: it is consumed by both
 * the server layout and client components.
 */
import type { Area } from "./rbac";

export type AdminNavChild = {
  label: string;
  href: string;
  /** Overrides the area inferred from the href (see RBAC note above). */
  area?: Area;
  /** Extra words the command palette should match on. */
  keywords?: string;
  /** Owner of a page not merged yet — the entry is hidden until removed. */
  pending?: string;
  /** Hidden behind a feature flag (`feature_admin_<flag>` setting). */
  flag?: "agency" | "ads";
};

export type AdminNavItem = AdminNavChild & {
  key: string;
  /** Icon name — see components/admin/shell/icons.tsx. */
  icon: string;
  /** Tucked behind the group's "More" disclosure. */
  more?: boolean;
  /** Sibling pages; `children[0]` is the item's landing page. */
  children?: AdminNavChild[];
};

export type AdminNavGroup = {
  key: string;
  /** Omitted for the lead-in group (Command center). */
  label?: string;
  items: AdminNavItem[];
};

