  more?: boolean;
};

/** Is this entry live (not pending) and allowed by the active feature flags? */
export function entryLive(e: AdminNavChild, flags: Partial<Record<"agency" | "ads", boolean>> = {}): boolean {
  if (e.pending) return false;
  if (e.flag && !flags[e.flag]) return false;
  return true;
}

/** Every live route in sidebar order (items, then their children), de-duplicated by href. */
export function flatAdminRoutes(groups: AdminNavGroup[] = ADMIN_NAV_GROUPS): FlatAdminRoute[] {
  const out: FlatAdminRoute[] = [];
  const seen = new Set<string>();
  for (const g of groups) {
    for (const it of g.items) {
      if (it.pending) continue;
      const push = (c: AdminNavChild, parent?: string) => {
        if (c.pending || seen.has(c.href)) return;
        seen.add(c.href);
        out.push({
          label: c.label, href: c.href, area: c.area ?? (parent ? undefined : it.area), keywords: c.keywords,
