/**
 * LEGACY SHIM — the admin IA now lives in `lib/admin-nav.ts` (2026-10-01
 * redesign). This module re-derives the old `ADMIN_NAV` shape
 * (section → entry → tabs) from that registry so any older import keeps
 * working; do not add entries here. Pending (not-yet-merged) and
 * feature-flagged entries are omitted.
 */
import { ADMIN_NAV_GROUPS, hrefMatches, entryLive } from "./admin-nav";

export { hrefMatches };

export type SubTabItem = { label: string; href: string };
export type AdminEntry = { key: string; label: string; icon: string; tabs: SubTabItem[] };
export type AdminGroup = { key: string; label?: string; entries: AdminEntry[] };

export const ADMIN_NAV: AdminGroup[] = ADMIN_NAV_GROUPS.map((g) => ({
  key: g.key,
  label: g.label,
  entries: g.items
    .filter((it) => entryLive(it, { agency: true, ads: true }))
    .map((it) => ({
      key: it.key,
      label: it.label,
      icon: it.icon,
      tabs: (it.children?.length ? it.children : [it])
        .filter((c) => !c.pending)
        .map((c) => ({ label: c.label, href: c.href })),
    })),
}));

/** Every entry across every section, in sidebar order. */
export function adminEntries(): AdminEntry[] {
  return ADMIN_NAV.flatMap((g) => g.entries);
}

/** Resolve which top-level entry owns a given admin pathname (longest match). */
export function entryForPath(pathname: string): AdminEntry | null {
  let best: { entry: AdminEntry; len: number } | null = null;
  for (const entry of adminEntries()) {
    for (const tab of entry.tabs) {
      if (hrefMatches(tab.href, pathname) && (!best || tab.href.length > best.len)) {
        best = { entry, len: tab.href.length };
      }
    }
  }
  return best?.entry ?? null;
}

