/* ═══════════════════════════════════════════════════════════════════════════
   ADMIN OPS PORTAL — visual layer (2026-10-01 redesign)

   Scope: EVERYTHING here sits under `:root.adm-portal`. That class is put on
   <html> only by the admin shell (an inline script in app/admin/layout.tsx
   before first paint, and components/admin/shell/AdminShell.tsx in a layout
   effect for client-side enter/exit). Marketing, /login, /register, the
   customer portal (`:root.nx-portal`) and the /staff portal (which still uses
   components/portal/Shell.tsx) never carry it, so nothing in this file can
   reach them — the same technique, and the same reason, as `:root.nx-portal`
   in app/globals.css. Do NOT add a bare selector to this file.

   Why `:root.<class>` and not `:root:has(.adm-shell-root)`: see the note above
   `:root.nx-portal` in app/globals.css — a root-anchored `:has()` makes Chrome
   restyle the whole document on every DOM insertion (traced at 50-70ms).

   Theme + density are attributes on <html> too (`data-adm-theme`,
   `data-adm-density`), deliberately NOT the customer portal's `data-theme`:
   app/globals.css has dozens of bare `html[data-theme="light"] …` rules tuned
   for the Nexion portal, and reusing that attribute would drag all of them in.

   Layering: tokens are unlayered custom properties (they only cascade). Every
   rule that touches a shared class (.card, .btn-*, .input, .table-shell …) is
   inside `@layer components` so that Tailwind utilities (`@layer utilities`)
   on a page — `card p-0`, `btn-primary w-full` — still win exactly as they did
   before. Do not move those rules out of the layer.

   @keyframes stay at top level (nested ones are silently dropped — CLAUDE.md).
   ═══════════════════════════════════════════════════════════════════════════ */

@keyframes adm-fade-up { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
@keyframes adm-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .45; } }
@keyframes adm-toast-in { from { opacity: 0; transform: translateY(8px) scale(.98); } to { opacity: 1; transform: none; } }
@keyframes adm-shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }

/* ── TOKENS · dark (default) ─────────────────────────────────────────────── */
:root.adm-portal {
  color-scheme: dark;

  /* Admin's own semantic tokens (used by the shell + new primitives). */
  --adm-ground: #050913;
  --adm-ground-2: #070c1a;
  --adm-surface: #0b1226;
  --adm-surface-2: #0f1831;
  --adm-surface-3: #15203f;
  --adm-rail: #060b18;
  --adm-line: rgba(138, 160, 255, 0.11);
  --adm-line-2: rgba(138, 160, 255, 0.19);
  --adm-line-3: rgba(160, 180, 255, 0.32);
  --adm-ink: #eaeefb;
  --adm-ink-2: #b9c2de;
  --adm-muted: #8792b4;
  --adm-faint: #5f6a8c;
  --adm-blue: #3b6be8;
  --adm-violet: #7b3fef;
  --adm-cyan: #3edcf2;
  --adm-green: #3fd89a;
  --adm-amber: #f2b64b;
  --adm-red: #f0607a;
  --adm-grad: linear-gradient(110deg, #3b6be8 0%, #7b3fef 100%);
  --adm-grad-aurora: linear-gradient(90deg, #3edcf2 0%, #3b6be8 40%, #7b3fef 100%);
  --adm-hover: rgba(138, 160, 255, 0.07);
  --adm-active: rgba(91, 95, 240, 0.16);
  --adm-shadow: 0 1px 0 0 rgba(255, 255, 255, 0.03) inset, 0 10px 34px -16px rgba(0, 0, 0, 0.7);
  --adm-radius: 14px;
  --adm-pad: 1.25rem;
  --adm-cell-y: 0.7rem;
  --adm-cell-x: 1rem;

  /* Tailwind palette slots, retinted to the marketing/Nexion language so the
     ~110 existing admin pages pick it up with no per-page edits. */
  --color-brand-50: #f1edff;
  --color-brand-100: #e2d9ff;
  --color-brand-200: #c9b8ff;
  --color-brand-300: #ab93ff;
  --color-brand-400: #9270fb;
  --color-brand-500: #7b3fef;
  --color-brand-600: #6a2fdc;
  --color-brand-700: #5825b8;
  --color-brand-800: #461f92;
  --color-brand-900: #391c74;

  --color-navy-950: #050913;
  --color-navy-900: #0b1226;
  --color-navy-850: #0d152c;
  --color-navy-800: #111a34;
  --color-navy-700: #18244a;
  --color-navy-600: #22305c;

  --color-accent-blue: #3b6be8;
  --color-accent-cyan: #3edcf2;

  --color-slate-50: #ffffff;
  --color-slate-100: #eaeefb;
  --color-slate-200: #d5dcf2;
  --color-slate-300: #b9c2de;
  --color-slate-400: #95a0c3;
  --color-slate-500: #7b86aa;
  --color-slate-600: #5f6a8c;
  --color-slate-700: #39446a;
  --color-slate-800: #1b2445;
  --color-slate-900: #0e1530;
  --color-slate-950: #070b1a;
}

/* ── TOKENS · light ──────────────────────────────────────────────────────── */
/* Same inversion trick as the customer portal's light mode (app/globals.css,
   `:root.nx-portal[data-theme="light"]`): the slate ramp and the navy surface
   ramp run the other way and `--color-white` becomes ink, so `text-slate-300`
   body copy and `text-white` headings stay readable on paper with no call
   site edited. Opacity variants of white are decoupled further down. */
:root.adm-portal[data-adm-theme="light"] {
  color-scheme: light;

  --adm-ground: #eef2f9;
  --adm-ground-2: #e7ecf6;
  --adm-surface: #ffffff;
  --adm-surface-2: #f6f8fd;
  --adm-surface-3: #edf1fa;
  --adm-rail: #f8faff;
  --adm-line: rgba(20, 40, 90, 0.10);
  --adm-line-2: rgba(20, 40, 90, 0.16);
  --adm-line-3: rgba(20, 40, 90, 0.26);
  --adm-ink: #0b1630;
  --adm-ink-2: #2a3a5c;
  --adm-muted: #56668a;
  --adm-faint: #8190ad;
  --adm-blue: #2f5fdc;
  --adm-violet: #6a2fdc;
  --adm-cyan: #0b91ab;
  --adm-green: #0a9c6f;
  --adm-amber: #b97708;
  --adm-red: #d02a54;
  --adm-hover: rgba(30, 60, 140, 0.06);
  --adm-active: rgba(91, 63, 239, 0.10);
  --adm-shadow: 0 1px 2px rgba(15, 30, 70, 0.06), 0 8px 24px -14px rgba(15, 30, 70, 0.18);

  --color-brand-50: #2b1366;
  --color-brand-100: #341a7a;
  --color-brand-200: #4a23a6;
  --color-brand-300: #5d2bcf;
  --color-brand-400: #6a2fdc;
  --color-brand-500: #6a2fdc;
  --color-brand-600: #5825b8;

  --color-accent-blue: #2f5fdc;
  --color-accent-cyan: #0b91ab;

  --color-navy-950: #ffffff;
  --color-navy-900: #ffffff;
  --color-navy-850: #f6f8fd;
  --color-navy-800: #eff3fb;
  --color-navy-700: #e2e8f5;
  --color-navy-600: #d2dbee;

  --color-slate-50: #0b1630;
  --color-slate-100: #111d3a;
  --color-slate-200: #1c2a4a;
  --color-slate-300: #2a3a5c;
  --color-slate-400: #4a5a7e;
  --color-slate-500: #5d6c8f;
  --color-slate-600: #7887a6;
  --color-slate-700: #a7b3cb;
  --color-slate-800: #d6deec;
  --color-slate-900: #e9eef7;
  --color-slate-950: #f5f7fc;

  --color-white: #0b1630;
}

/* ── DENSITY ─────────────────────────────────────────────────────────────── */
:root.adm-portal[data-adm-density="compact"] {
  --adm-pad: 0.9rem;
  --adm-cell-y: 0.42rem;
  --adm-cell-x: 0.75rem;
}

/* ── PAGE GROUND ─────────────────────────────────────────────────────────── */
:root.adm-portal body {
  background-color: var(--adm-ground);
  color: var(--adm-ink-2);
  background-image:
    radial-gradient(1100px 520px at 85% -14%, rgba(59, 107, 232, 0.10), transparent 62%),
    radial-gradient(900px 480px at -6% 108%, rgba(123, 63, 239, 0.08), transparent 66%);
  background-attachment: fixed;
}
:root.adm-portal[data-adm-theme="light"] body {
  background-image:
    radial-gradient(1100px 520px at 85% -14%, rgba(59, 107, 232, 0.07), transparent 62%),
    radial-gradient(900px 480px at -6% 108%, rgba(123, 63, 239, 0.05), transparent 66%);
}

/* ── SHARED COMPONENT CLASSES, RESKINNED (inside the components layer) ──── */
@layer components {
  :root.adm-portal .card {
    border-radius: var(--adm-radius);
    border-color: var(--adm-line);
    background-color: color-mix(in srgb, var(--adm-surface) 88%, transparent);
    box-shadow: var(--adm-shadow);
    padding: var(--adm-pad);
    /* No backdrop-filter: it turns the card into the containing block for any
       non-portaled `position: fixed` modal inside it (CLAUDE.md landmine), and
       the admin ground is flat enough that the blur bought nothing visible. */
    backdrop-filter: none;
  }
  :root.adm-portal .card-hover:hover {
    border-color: var(--adm-line-3);
    background-color: var(--adm-surface-2);
  }
  :root.adm-portal .glass {
    border-color: var(--adm-line);
    background-color: color-mix(in srgb, var(--adm-surface) 70%, transparent);
  }
  :root.adm-portal .page-title {
    font-size: 1.5rem;
    line-height: 2rem;
    font-weight: 650;
    letter-spacing: -0.02em;
    color: var(--adm-ink);
  }
  :root.adm-portal .section-label {
    color: var(--adm-faint);
    letter-spacing: 0.12em;
  }

  :root.adm-portal .btn-primary,
  :root.adm-portal .btn-secondary,
  :root.adm-portal .btn-danger,
  :root.adm-portal .btn-ghost {
    border-radius: 10px;
    font-weight: 600;
  }
  :root.adm-portal .btn-primary {
    background-image: var(--adm-grad);
    color: #fff;
    box-shadow: 0 6px 20px -8px rgba(91, 63, 239, 0.65), inset 0 1px 0 rgba(255, 255, 255, 0.16);
  }
  :root.adm-portal .btn-primary:hover { filter: brightness(1.08); }
  :root.adm-portal .btn-secondary {
    border-color: var(--adm-line-2);
    background-color: var(--adm-surface-2);
    color: var(--adm-ink);
  }
  :root.adm-portal .btn-secondary:hover {
    border-color: var(--adm-line-3);
    background-color: var(--adm-surface-3);
  }
  :root.adm-portal .btn-ghost { color: var(--adm-muted); }
  :root.adm-portal .btn-ghost:hover { background-color: var(--adm-hover); color: var(--adm-ink); }
  :root.adm-portal .btn-danger { color: var(--adm-red); }

  :root.adm-portal .input {
    border-radius: 10px;
    border-color: var(--adm-line-2);
    background-color: var(--adm-ground-2);
    color: var(--adm-ink);
  }
  :root.adm-portal .input:focus {
    border-color: color-mix(in srgb, var(--adm-blue) 70%, transparent);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--adm-blue) 22%, transparent);
  }
  :root.adm-portal .label { color: var(--adm-muted); }

  :root.adm-portal .table-shell thead th {
    color: var(--adm-faint);
    padding: calc(var(--adm-cell-y) * 0.9) var(--adm-cell-x);
    letter-spacing: 0.08em;
    font-weight: 600;
    background: color-mix(in srgb, var(--adm-surface-2) 55%, transparent);
    position: sticky;
    top: 0;
    z-index: 1;
  }
  :root.adm-portal .table-shell tbody tr { border-color: var(--adm-line); }
  :root.adm-portal .table-shell tbody tr:hover { background-color: var(--adm-hover); }
  :root.adm-portal .table-shell tbody td { padding: var(--adm-cell-y) var(--adm-cell-x); }

  :root.adm-portal .kbd {
    border-color: var(--adm-line-2);
    background-color: var(--adm-surface-2);
    color: var(--adm-muted);
  }
  :root.adm-portal .divider { border-color: var(--adm-line); }
  :root.adm-portal .skeleton {
    background: linear-gradient(90deg, var(--adm-surface-2) 25%, var(--adm-surface-3) 37%, var(--adm-surface-2) 63%);
    background-size: 400% 100%;
    animation: adm-shimmer 1.4s ease infinite;
  }
  :root.adm-portal .grad-text {
    background-image: var(--adm-grad-aurora);
  }
}

/* ── LIGHT MODE: opacity-modified white utilities ───────────────────────── */
/* `bg-white/[0.04]`, `border-white/10`, `text-white/70` are lighteners tuned
   for a dark base; with `--color-white` flipped to ink they would turn into
   grey smudges. Same decoupling as the customer portal (app/globals.css),
   matched on the literal class text, excluding `.adm-dark` islands (chips and
   panels that stay dark in both themes). Unlayered + !important on purpose:
   they must beat the utility they retarget. */
:root.adm-portal[data-adm-theme="light"] [class*="bg-white/"]:not(.adm-dark, .adm-dark *) {
  background-color: color-mix(in srgb, var(--adm-ink) 5%, transparent) !important;
}
:root.adm-portal[data-adm-theme="light"] [class*="border-white/"]:not(.adm-dark, .adm-dark *) {
  border-color: var(--adm-line-2) !important;
}
:root.adm-portal[data-adm-theme="light"] [class*="text-white/"]:not(.adm-dark, .adm-dark *) {
  color: color-mix(in srgb, var(--adm-ink) 68%, transparent) !important;
}
:root.adm-portal[data-adm-theme="light"] [class*="divide-white/"]:not(.adm-dark, .adm-dark *) > * + * {
  border-color: var(--adm-line) !important;
}
/* A `text-white` on a saturated gradient/brand fill wants literal white in
   both themes (badges, solid buttons, avatar initials). */
:root.adm-portal[data-adm-theme="light"] [class*="bg-gradient-to-"][class~="text-white"],
:root.adm-portal[data-adm-theme="light"] [class~="bg-brand-500"][class~="text-white"],
:root.adm-portal[data-adm-theme="light"] [class~="bg-brand-600"][class~="text-white"],
:root.adm-portal[data-adm-theme="light"] [class~="bg-red-500"][class~="text-white"],
:root.adm-portal[data-adm-theme="light"] [class~="bg-emerald-500"][class~="text-white"] {
  color: #fff !important;
}
/* Native date/time pickers forced dark by `[color-scheme:dark]`. */
:root.adm-portal[data-adm-theme="light"] [class*="color-scheme:dark"]:not(.adm-dark, .adm-dark *) {
  color-scheme: light;
}
/* Pastel status text tuned for dark (text-emerald-300 etc.) — pull darker. */
:root.adm-portal[data-adm-theme="light"] [class~="text-emerald-300"],
:root.adm-portal[data-adm-theme="light"] [class~="text-emerald-400"] { color: #0a8a62 !important; }
:root.adm-portal[data-adm-theme="light"] [class~="text-amber-300"],
:root.adm-portal[data-adm-theme="light"] [class~="text-amber-400"],
:root.adm-portal[data-adm-theme="light"] [class~="text-amber-200"] { color: #a15f00 !important; }
:root.adm-portal[data-adm-theme="light"] [class~="text-red-300"],
:root.adm-portal[data-adm-theme="light"] [class~="text-red-400"] { color: #c22048 !important; }
:root.adm-portal[data-adm-theme="light"] [class~="text-cyan-300"],
:root.adm-portal[data-adm-theme="light"] [class~="text-sky-300"] { color: #087f97 !important; }

/* ══ SHELL ══════════════════════════════════════════════════════════════════
   Everything below is the admin shell's own classes (`adm-` prefix, used only
   by components/admin/shell/*). */
:root.adm-portal .adm-shell-root {
  display: flex;
  min-height: 100vh;
  color: var(--adm-ink-2);
}

/* sidebar */
:root.adm-portal .adm-rail {
  position: fixed;
  inset: 0 auto 0 0;
  z-index: 40;
  display: flex;
  flex-direction: column;
  width: 16rem;
  background: var(--adm-rail);
  border-right: 1px solid var(--adm-line);
  transform: translateX(-100%);
  transition: transform 0.22s cubic-bezier(.22, 1, .36, 1), width 0.18s ease;
}
:root.adm-portal .adm-rail[data-open="true"] { transform: none; box-shadow: 0 0 60px rgba(0, 0, 0, 0.45); }
@media (min-width: 1024px) {
  :root.adm-portal .adm-rail {
    position: sticky;
    top: 0;
    height: 100vh;
    transform: none;
    flex-shrink: 0;
  }
  :root.adm-portal .adm-rail[data-collapsed="true"] { width: 4.25rem; }
}
:root.adm-portal .adm-rail-head {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  height: 3.75rem;
  padding: 0 0.9rem 0 1rem;
  border-bottom: 1px solid var(--adm-line);
}
:root.adm-portal .adm-rail-nav {
  flex: 1;
  overflow-y: auto;
  padding: 0.6rem 0.6rem 1.25rem;
  scrollbar-width: thin;
}
:root.adm-portal .adm-group + .adm-group { margin-top: 0.85rem; }
:root.adm-portal .adm-group-head {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem;
  padding: 0.3rem 0.6rem;
  border-radius: 8px;
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--adm-faint);
}
:root.adm-portal .adm-group-head:hover { color: var(--adm-ink-2); }
:root.adm-portal .adm-group-head:focus-visible,
:root.adm-portal .adm-nav-row:focus-visible,
:root.adm-portal .adm-iconbtn:focus-visible,
:root.adm-portal .adm-more:focus-visible {
  outline: 2px solid var(--adm-cyan);
  outline-offset: 1px;
}
:root.adm-portal .adm-nav-row {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.65rem;
  min-height: 2.15rem;
  padding: 0.38rem 0.6rem;
  border-radius: 9px;
  font-size: 13.5px;
  font-weight: 520;
  color: var(--adm-ink-2);
  transition: background-color 0.12s ease, color 0.12s ease;
}
:root.adm-portal .adm-nav-row:hover { background: var(--adm-hover); color: var(--adm-ink); }
:root.adm-portal .adm-nav-row svg { flex-shrink: 0; color: var(--adm-muted); }
:root.adm-portal .adm-nav-row[aria-current="page"],
:root.adm-portal .adm-nav-row[data-active="true"] {
  background: var(--adm-active);
  color: var(--adm-ink);
}
:root.adm-portal .adm-nav-row[data-active="true"]::before {
  content: "";
  position: absolute;
  left: -0.6rem;
  top: 0.45rem;
  bottom: 0.45rem;
  width: 3px;
  border-radius: 0 3px 3px 0;
  background: var(--adm-grad-aurora);
}
:root.adm-portal .adm-nav-row[data-active="true"] svg { color: var(--adm-cyan); }
:root.adm-portal .adm-nav-sub {
  margin: 0.15rem 0 0.35rem 1.45rem;
  padding-left: 0.65rem;
  border-left: 1px solid var(--adm-line);
}
:root.adm-portal .adm-nav-sub .adm-nav-row { min-height: 1.85rem; font-size: 12.75px; padding: 0.25rem 0.55rem; color: var(--adm-muted); }
:root.adm-portal .adm-nav-sub .adm-nav-row[aria-current="page"] { color: var(--adm-ink); background: var(--adm-hover); }
:root.adm-portal .adm-count {
  margin-left: auto;
  display: inline-flex;
  min-width: 1.15rem;
  height: 1.15rem;
  align-items: center;
  justify-content: center;
  padding: 0 0.35rem;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 700;
  color: #fff;
  background: var(--adm-grad);
}
:root.adm-portal .adm-count[data-tone="red"] { background: #e23d63; }
:root.adm-portal .adm-dot {
  position: absolute;
  right: 0.35rem;
  top: 0.35rem;
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 999px;
  background: var(--adm-violet);
  box-shadow: 0 0 0 2px var(--adm-rail);
}
:root.adm-portal .adm-more {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 0.5rem;
  padding: 0.3rem 0.6rem;
  border-radius: 8px;
  font-size: 12px;
  color: var(--adm-faint);
}
:root.adm-portal .adm-more:hover { color: var(--adm-ink-2); background: var(--adm-hover); }
:root.adm-portal .adm-rail-foot {
  border-top: 1px solid var(--adm-line);
  padding: 0.6rem;
}
@media (min-width: 1024px) {
  :root.adm-portal .adm-rail[data-collapsed="true"] .adm-hide-collapsed { display: none !important; }
  :root.adm-portal .adm-rail[data-collapsed="true"] .adm-nav-row { justify-content: center; padding-inline: 0; }
  :root.adm-portal .adm-rail[data-collapsed="true"] .adm-nav-row[data-active="true"]::before { left: -0.6rem; }
  :root.adm-portal .adm-rail[data-collapsed="true"] .adm-rail-head { justify-content: center; padding: 0; }
}
:root.adm-portal .adm-rail:not([data-collapsed="true"]) .adm-show-collapsed { display: none; }
@media (max-width: 1023px) { :root.adm-portal .adm-show-collapsed { display: none; } }

:root.adm-portal .adm-scrim {
  position: fixed;
  inset: 0;
  z-index: 35;
  background: rgba(2, 5, 14, 0.55);
  backdrop-filter: blur(2px);
}

/* topbar */
:root.adm-portal .adm-topbar {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: 0.6rem;
  height: 3.75rem;
  padding: 0 1rem;
  border-bottom: 1px solid var(--adm-line);
  background: color-mix(in srgb, var(--adm-ground) 82%, transparent);
  backdrop-filter: blur(14px) saturate(1.2);
}
@media (min-width: 640px) { :root.adm-portal .adm-topbar { padding: 0 1.5rem; } }
:root.adm-portal .adm-search {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  width: 100%;
  max-width: 26rem;
  height: 2.35rem;
  padding: 0 0.75rem;
  border-radius: 10px;
  border: 1px solid var(--adm-line-2);
  background: var(--adm-surface);
  font-size: 13px;
  color: var(--adm-muted);
  transition: border-color 0.12s ease;
}
:root.adm-portal .adm-search:hover { border-color: var(--adm-line-3); }
:root.adm-portal .adm-iconbtn {
  position: relative;
  display: inline-flex;
  width: 2.35rem;
  height: 2.35rem;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  color: var(--adm-muted);
  transition: background-color 0.12s ease, color 0.12s ease;
}
:root.adm-portal .adm-iconbtn:hover { background: var(--adm-hover); color: var(--adm-ink); }
:root.adm-portal .adm-iconbtn[aria-pressed="true"] { color: var(--adm-cyan); }
:root.adm-portal .adm-badge-dot {
  position: absolute;
  top: 0.3rem;
  right: 0.3rem;
  min-width: 1rem;
  height: 1rem;
  padding: 0 0.25rem;
  border-radius: 999px;
  font-size: 9.5px;
  font-weight: 700;
  line-height: 1rem;
  text-align: center;
  color: #fff;
  background: #e23d63;
  box-shadow: 0 0 0 2px var(--adm-ground);
}
:root.adm-portal .adm-badge-dot[data-tone="brand"] { background: var(--adm-grad); }

/* popovers (alerts tray, account menu) */
:root.adm-portal .adm-pop {
  position: absolute;
  right: 0;
  top: calc(100% + 0.5rem);
  z-index: 50;
  width: min(24rem, calc(100vw - 2rem));
  overflow: hidden;
  border-radius: 14px;
  border: 1px solid var(--adm-line-2);
  background: var(--adm-surface);
  box-shadow: 0 24px 60px -20px rgba(0, 0, 0, 0.6);
  animation: adm-fade-up 0.14s ease;
}
:root.adm-portal .adm-pop-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--adm-line);
  font-size: 13px;
  font-weight: 650;
  color: var(--adm-ink);
}
:root.adm-portal .adm-pop-row {
  display: flex;
  gap: 0.7rem;
  padding: 0.7rem 1rem;
  border-bottom: 1px solid var(--adm-line);
  font-size: 13px;
}
:root.adm-portal a.adm-pop-row:hover { background: var(--adm-hover); }
:root.adm-portal .adm-tabs { display: flex; gap: 0.25rem; padding: 0.4rem 0.6rem; border-bottom: 1px solid var(--adm-line); }
:root.adm-portal .adm-tab {
  padding: 0.3rem 0.6rem;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 600;
  color: var(--adm-muted);
}
:root.adm-portal .adm-tab[aria-selected="true"] { background: var(--adm-active); color: var(--adm-ink); }

/* content */
:root.adm-portal .adm-main {
  width: 100%;
  margin: 0 auto;
  padding: 1.25rem 1rem 3rem;
  animation: adm-fade-up 0.2s ease;
}
@media (min-width: 640px) { :root.adm-portal .adm-main { padding: 1.5rem 1.75rem 3.5rem; } }
:root.adm-portal .adm-crumbs {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
  margin-bottom: 0.9rem;
  font-size: 12px;
  color: var(--adm-faint);
}
:root.adm-portal .adm-crumbs a:hover { color: var(--adm-ink); }
:root.adm-portal .adm-crumbs [aria-current="page"] { color: var(--adm-ink-2); }

/* sub-tab bar (components/admin/SubTabs.tsx) */
:root.adm-portal .adm-subtabs {
  display: flex;
  gap: 0.15rem;
  margin-bottom: 1.25rem;
  overflow-x: auto;
  border-bottom: 1px solid var(--adm-line);
  scrollbar-width: none;
}
:root.adm-portal .adm-subtabs::-webkit-scrollbar { display: none; }
:root.adm-portal .adm-subtab {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.45rem;
  padding: 0.55rem 0.8rem 0.65rem;
  font-size: 13px;
  font-weight: 560;
  color: var(--adm-muted);
  white-space: nowrap;
}
:root.adm-portal .adm-subtab:hover { color: var(--adm-ink); }
:root.adm-portal .adm-subtab[aria-current="page"] { color: var(--adm-ink); }
:root.adm-portal .adm-subtab[aria-current="page"]::after {
  content: "";
  position: absolute;
  left: 0.6rem;
  right: 0.6rem;
  bottom: -1px;
  height: 2px;
  border-radius: 2px;
  background: var(--adm-grad-aurora);
}

/* new primitives (components/admin/shell/primitives.tsx) */
:root.adm-portal .adm-eyebrow {
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--adm-cyan);
}
:root.adm-portal .adm-panel {
  border-radius: var(--adm-radius);
  border: 1px solid var(--adm-line);
  background: color-mix(in srgb, var(--adm-surface) 90%, transparent);
  box-shadow: var(--adm-shadow);
}
:root.adm-portal .adm-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.9rem var(--adm-pad) 0.75rem;
  border-bottom: 1px solid var(--adm-line);
}
:root.adm-portal .adm-panel-title { font-size: 14px; font-weight: 650; color: var(--adm-ink); }
:root.adm-portal .adm-panel-link { font-size: 12px; font-weight: 600; color: var(--adm-blue); }
:root.adm-portal[data-adm-theme="dark"] .adm-panel-link,
:root.adm-portal:not([data-adm-theme]) .adm-panel-link { color: #86a8ff; }
:root.adm-portal .adm-panel-link:hover { text-decoration: underline; }
:root.adm-portal .adm-kpi {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  min-height: 7rem;
  padding: var(--adm-pad);
  border-radius: var(--adm-radius);
  border: 1px solid var(--adm-line);
  background: color-mix(in srgb, var(--adm-surface) 90%, transparent);
  box-shadow: var(--adm-shadow);
  transition: border-color 0.14s ease, transform 0.14s ease;
}
:root.adm-portal a.adm-kpi:hover { border-color: var(--adm-line-3); transform: translateY(-1px); }
:root.adm-portal .adm-kpi[data-tone="alert"] { border-color: color-mix(in srgb, var(--adm-red) 45%, transparent); }
:root.adm-portal .adm-kpi[data-tone="warn"] { border-color: color-mix(in srgb, var(--adm-amber) 45%, transparent); }
:root.adm-portal .adm-kpi-label { font-size: 12.5px; font-weight: 550; color: var(--adm-muted); }
:root.adm-portal .adm-kpi-value { font-size: 1.65rem; font-weight: 700; letter-spacing: -0.02em; color: var(--adm-ink); font-variant-numeric: tabular-nums; }
:root.adm-portal .adm-kpi-sub { font-size: 12px; color: var(--adm-faint); }
:root.adm-portal .adm-delta { display: inline-flex; align-items: center; gap: 0.2rem; font-size: 12px; font-weight: 650; font-variant-numeric: tabular-nums; }
:root.adm-portal .adm-delta[data-dir="up"] { color: var(--adm-green); }
:root.adm-portal .adm-delta[data-dir="down"] { color: var(--adm-red); }
:root.adm-portal .adm-delta[data-dir="flat"] { color: var(--adm-faint); }
:root.adm-portal .adm-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.12rem 0.55rem;
  border-radius: 999px;
  border: 1px solid var(--adm-line-2);
  font-size: 11.5px;
  font-weight: 600;
  color: var(--adm-ink-2);
  white-space: nowrap;
}
:root.adm-portal .adm-pill[data-tone="green"] { color: var(--adm-green); border-color: color-mix(in srgb, var(--adm-green) 40%, transparent); background: color-mix(in srgb, var(--adm-green) 9%, transparent); }
:root.adm-portal .adm-pill[data-tone="red"] { color: var(--adm-red); border-color: color-mix(in srgb, var(--adm-red) 40%, transparent); background: color-mix(in srgb, var(--adm-red) 9%, transparent); }
:root.adm-portal .adm-pill[data-tone="amber"] { color: var(--adm-amber); border-color: color-mix(in srgb, var(--adm-amber) 40%, transparent); background: color-mix(in srgb, var(--adm-amber) 9%, transparent); }
:root.adm-portal .adm-pill[data-tone="blue"] { color: #86a8ff; border-color: color-mix(in srgb, var(--adm-blue) 45%, transparent); background: color-mix(in srgb, var(--adm-blue) 10%, transparent); }
:root.adm-portal[data-adm-theme="light"] .adm-pill[data-tone="blue"] { color: var(--adm-blue); }
:root.adm-portal .adm-meter { height: 6px; border-radius: 999px; background: var(--adm-surface-3); overflow: hidden; }
:root.adm-portal .adm-meter > span { display: block; height: 100%; border-radius: inherit; background: var(--adm-grad); }
:root.adm-portal .adm-meter[data-tone="warn"] > span { background: var(--adm-amber); }
:root.adm-portal .adm-meter[data-tone="alert"] > span { background: var(--adm-red); }
:root.adm-portal .adm-list > * + * { border-top: 1px solid var(--adm-line); }
:root.adm-portal .adm-live { width: 0.5rem; height: 0.5rem; border-radius: 999px; background: var(--adm-green); animation: adm-pulse 2s ease infinite; }

/* command palette */
:root.adm-portal .adm-cmdk-scrim {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 12vh 1rem 1rem;
  background: rgba(2, 5, 14, 0.6);
  backdrop-filter: blur(3px);
}
:root.adm-portal .adm-cmdk {
  width: 100%;
  max-width: 40rem;
  overflow: hidden;
  border-radius: 16px;
  border: 1px solid var(--adm-line-2);
  background: var(--adm-surface);
  box-shadow: 0 40px 90px -30px rgba(0, 0, 0, 0.75);
  animation: adm-fade-up 0.14s ease;
}
:root.adm-portal .adm-cmdk input {
  width: 100%;
  height: 3.25rem;
  padding: 0 1rem 0 2.75rem;
  border: 0;
  border-bottom: 1px solid var(--adm-line);
  background: transparent;
  color: var(--adm-ink);
  font-size: 15px;
  outline: none;
}
:root.adm-portal .adm-cmdk-list { max-height: min(60vh, 28rem); overflow-y: auto; padding: 0.4rem; }
:root.adm-portal .adm-cmdk-sec { padding: 0.55rem 0.7rem 0.3rem; font-size: 10.5px; font-weight: 650; letter-spacing: 0.12em; text-transform: uppercase; color: var(--adm-faint); }
:root.adm-portal .adm-cmdk-opt {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  width: 100%;
  padding: 0.5rem 0.7rem;
  border-radius: 9px;
  font-size: 13.5px;
  color: var(--adm-ink-2);
  text-align: left;
}
:root.adm-portal .adm-cmdk-opt[aria-selected="true"] { background: var(--adm-active); color: var(--adm-ink); }
:root.adm-portal .adm-cmdk-opt small { color: var(--adm-faint); font-size: 11.5px; }

/* toasts */
:root.adm-portal .adm-toasts {
  position: fixed;
  z-index: 90;
  right: 1rem;
  bottom: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  width: min(22rem, calc(100vw - 2rem));
}
:root.adm-portal .adm-toast {
  display: flex;
  gap: 0.6rem;
  padding: 0.75rem 0.9rem;
  border-radius: 12px;
  border: 1px solid var(--adm-line-2);
  background: var(--adm-surface);
  box-shadow: 0 18px 50px -20px rgba(0, 0, 0, 0.6);
  font-size: 13px;
  color: var(--adm-ink);
  animation: adm-toast-in 0.18s ease;
}
:root.adm-portal .adm-toast[data-tone="error"] { border-color: color-mix(in srgb, var(--adm-red) 50%, transparent); }
:root.adm-portal .adm-toast[data-tone="success"] { border-color: color-mix(in srgb, var(--adm-green) 50%, transparent); }

/* avatar + logo */
:root.adm-portal .adm-avatar {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: 999px;
  font-weight: 700;
  color: #fff;
  background: var(--adm-grad);
  user-select: none;
}
:root.adm-portal .adm-avatar img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
:root.adm-portal .adm-wordmark {
  font-weight: 800;
  letter-spacing: 0.16em;
  font-size: 15px;
  color: var(--adm-ink);
}
:root.adm-portal .adm-env {
  border-radius: 6px;
  padding: 0.1rem 0.4rem;
  font-size: 9.5px;
  font-weight: 750;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--adm-cyan);
  border: 1px solid color-mix(in srgb, var(--adm-cyan) 35%, transparent);
  background: color-mix(in srgb, var(--adm-cyan) 8%, transparent);
}
:root.adm-portal[data-adm-theme="light"] .adm-logo-dark { display: none; }
:root.adm-portal:not([data-adm-theme="light"]) .adm-logo-light { display: none; }

@media (prefers-reduced-motion: reduce) {
  :root.adm-portal .adm-main,
  :root.adm-portal .adm-pop,
  :root.adm-portal .adm-cmdk,
  :root.adm-portal .adm-toast { animation: none; }
  :root.adm-portal .adm-rail { transition: none; }
}

toolu_01MCj9GbJvhFKjRRrnBb5xAr.content:
/* ═══════════════════════════════════════════════════════════════════════════
   ADMIN OPS PORTAL — visual layer (2026-10-01 redesign)

   Scope: EVERYTHING here sits under `:root.adm-portal`. That class is put on
   <html> only by the admin shell (an inline script in app/admin/layout.tsx
   before first paint, and components/admin/shell/AdminShell.tsx in a layout
   effect for client-side enter/exit). Marketing, /login, /register, the
   customer portal (`:root.nx-portal`) and the /staff portal (which still uses
   components/portal/Shell.tsx) never carry it, so nothing in this file can
   reach them — the same technique, and the same reason, as `:root.nx-portal`
   in app/globals.css. Do NOT add a bare selector to this file.

   Why `:root.<class>` and not `:root:has(.adm-shell-root)`: see the note above
   `:root.nx-portal` in app/globals.css — a root-anchored `:has()` makes Chrome
   restyle the whole document on every DOM insertion (traced at 50-70ms).

   Theme + density are attributes on <html> too (`data-adm-theme`,
   `data-adm-density`), deliberately NOT the customer portal's `data-theme`:
   app/globals.css has dozens of bare `html[data-theme="light"] …` rules tuned
   for the Nexion portal, and reusing that attribute would drag all of them in.

   Layering: tokens are unlayered custom properties (they only cascade). Every
   rule that touches a shared class (.card, .btn-*, .input, .table-shell …) is
   inside `@layer components` so that Tailwind utilities (`@layer utilities`)
   on a page — `card p-0`, `btn-primary w-full` — still win exactly as they did
   before. Do not move those rules out of the layer.

   @keyframes stay at top level (nested ones are silently dropped — CLAUDE.md).
   ═══════════════════════════════════════════════════════════════════════════ */

@keyframes adm-fade-up { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
@keyframes adm-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .45; } }
@keyframes adm-toast-in { from { opacity: 0; transform: translateY(8px) scale(.98); } to { opacity: 1; transform: none; } }
@keyframes adm-shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }

/* ── TOKENS · dark (default) ─────────────────────────────────────────────── */
:root.adm-portal {
  color-scheme: dark;

  /* Admin's own semantic tokens (used by the shell + new primitives). */
  --adm-ground: #050913;
  --adm-ground-2: #070c1a;
  --adm-surface: #0b1226;
  --adm-surface-2: #0f1831;
  --adm-surface-3: #15203f;
  --adm-rail: #060b18;
  --adm-line: rgba(138, 160, 255, 0.11);
  --adm-line-2: rgba(138, 160, 255, 0.19);
  --adm-line-3: rgba(160, 180, 255, 0.32);
  --adm-ink: #eaeefb;
  --adm-ink-2: #b9c2de;
  --adm-muted: #8792b4;
  --adm-faint: #5f6a8c;
  --adm-blue: #3b6be8;
  --adm-violet: #7b3fef;
  --adm-cyan: #3edcf2;
  --adm-green: #3fd89a;
  --adm-amber: #f2b64b;
  --adm-red: #f0607a;
  --adm-grad: linear-gradient(110deg, #3b6be8 0%, #7b3fef 100%);
  --adm-grad-aurora: linear-gradient(90deg, #3edcf2 0%, #3b6be8 40%, #7b3fef 100%);
  --adm-hover: rgba(138, 160, 255, 0.07);
  --adm-active: rgba(91, 95, 240, 0.16);
  --adm-shadow: 0 1px 0 0 rgba(255, 255, 255, 0.03) inset, 0 10px 34px -16px rgba(0, 0, 0, 0.7);
  --adm-radius: 14px;
  --adm-pad: 1.25rem;
  --adm-cell-y: 0.7rem;
  --adm-cell-x: 1rem;

  /* Tailwind palette slots, retinted to the marketing/Nexion language so the
     ~110 existing admin pages pick it up with no per-page edits. */
  --color-brand-50: #f1edff;
  --color-brand-100: #e2d9ff;
  --color-brand-200: #c9b8ff;
  --color-brand-300: #ab93ff;
  --color-brand-400: #9270fb;
  --color-brand-500: #7b3fef;
  --color-brand-600: #6a2fdc;
  --color-brand-700: #5825b8;
  --color-brand-800: #461f92;
  --color-brand-900: #391c74;

  --color-navy-950: #050913;
  --color-navy-900: #0b1226;
  --color-navy-850: #0d152c;
  --color-navy-800: #111a34;
  --color-navy-700: #18244a;
  --color-navy-600: #22305c;

  --color-accent-blue: #3b6be8;
  --color-accent-cyan: #3edcf2;

  --color-slate-50: #ffffff;
  --color-slate-100: #eaeefb;
  --color-slate-200: #d5dcf2;
  --color-slate-300: #b9c2de;
  --color-slate-400: #95a0c3;
  --color-slate-500: #7b86aa;
  --color-slate-600: #5f6a8c;
  --color-slate-700: #39446a;
  --color-slate-800: #1b2445;
  --color-slate-900: #0e1530;
  --color-slate-950: #070b1a;
}

/* ── TOKENS · light ──────────────────────────────────────────────────────── */
/* Same inversion trick as the customer portal's light mode (app/globals.css,
   `:root.nx-portal[data-theme="light"]`): the slate ramp and the navy surface
   ramp run the other way and `--color-white` becomes ink, so `text-slate-300`
   body copy and `text-white` headings stay readable on paper with no call
   site edited. Opacity variants of white are decoupled further down. */
:root.adm-portal[data-adm-theme="light"] {
  color-scheme: light;

  --adm-ground: #eef2f9;
  --adm-ground-2: #e7ecf6;
  --adm-surface: #ffffff;
  --adm-surface-2: #f6f8fd;
  --adm-surface-3: #edf1fa;
  --adm-rail: #f8faff;
  --adm-line: rgba(20, 40, 90, 0.10);
  --adm-line-2: rgba(20, 40, 90, 0.16);
  --adm-line-3: rgba(20, 40, 90, 0.26);
  --adm-ink: #0b1630;
  --adm-ink-2: #2a3a5c;
  --adm-muted: #56668a;
  --adm-faint: #8190ad;
  --adm-blue: #2f5fdc;
  --adm-violet: #6a2fdc;
  --adm-cyan: #0b91ab;
  --adm-green: #0a9c6f;
  --adm-amber: #b97708;
  --adm-red: #d02a54;
  --adm-hover: rgba(30, 60, 140, 0.06);
  --adm-active: rgba(91, 63, 239, 0.10);
  --adm-shadow: 0 1px 2px rgba(15, 30, 70, 0.06), 0 8px 24px -14px rgba(15, 30, 70, 0.18);

  --color-brand-50: #2b1366;
  --color-brand-100: #341a7a;
  --color-brand-200: #4a23a6;
  --color-brand-300: #5d2bcf;
  --color-brand-400: #6a2fdc;
  --color-brand-500: #6a2fdc;
  --color-brand-600: #5825b8;

  --color-accent-blue: #2f5fdc;
  --color-accent-cyan: #0b91ab;

  --color-navy-950: #ffffff;
  --color-navy-900: #ffffff;
  --color-navy-850: #f6f8fd;
  --color-navy-800: #eff3fb;
  --color-navy-700: #e2e8f5;
  --color-navy-600: #d2dbee;

  --color-slate-50: #0b1630;
  --color-slate-100: #111d3a;
  --color-slate-200: #1c2a4a;
  --color-slate-300: #2a3a5c;
  --color-slate-400: #4a5a7e;
  --color-slate-500: #5d6c8f;
  --color-slate-600: #7887a6;
  --color-slate-700: #a7b3cb;
  --color-slate-800: #d6deec;
  --color-slate-900: #e9eef7;
  --color-slate-950: #f5f7fc;

  --color-white: #0b1630;
}

/* ── DENSITY ─────────────────────────────────────────────────────────────── */
:root.adm-portal[data-adm-density="compact"] {
  --adm-pad: 0.9rem;
  --adm-cell-y: 0.42rem;
  --adm-cell-x: 0.75rem;
}

/* ── PAGE GROUND ─────────────────────────────────────────────────────────── */
:root.adm-portal body {
  background-color: var(--adm-ground);
  color: var(--adm-ink-2);
  background-image:
    radial-gradient(1100px 520px at 85% -14%, rgba(59, 107, 232, 0.10), transparent 62%),
    radial-gradient(900px 480px at -6% 108%, rgba(123, 63, 239, 0.08), transparent 66%);
  background-attachment: fixed;
}
:root.adm-portal[data-adm-theme="light"] body {
  background-image:
    radial-gradient(1100px 520px at 85% -14%, rgba(59, 107, 232, 0.07), transparent 62%),
    radial-gradient(900px 480px at -6% 108%, rgba(123, 63, 239, 0.05), transparent 66%);
}

/* ── SHARED COMPONENT CLASSES, RESKINNED (inside the components layer) ──── */
@layer components {
  :root.adm-portal .card {
    border-radius: var(--adm-radius);
    border-color: var(--adm-line);
    background-color: color-mix(in srgb, var(--adm-surface) 88%, transparent);
    box-shadow: var(--adm-shadow);
    padding: var(--adm-pad);
    /* No backdrop-filter: it turns the card into the containing block for any
       non-portaled `position: fixed` modal inside it (CLAUDE.md landmine), and
       the admin ground is flat enough that the blur bought nothing visible. */
    backdrop-filter: none;
  }
  :root.adm-portal .card-hover:hover {
    border-color: var(--adm-line-3);
    background-color: var(--adm-surface-2);
  }
  :root.adm-portal .glass {
    border-color: var(--adm-line);
    background-color: color-mix(in srgb, var(--adm-surface) 70%, transparent);
  }
  :root.adm-portal .page-title {
    font-size: 1.5rem;
    line-height: 2rem;
    font-weight: 650;
    letter-spacing: -0.02em;
    color: var(--adm-ink);
  }
  :root.adm-portal .section-label {
    color: var(--adm-faint);
    letter-spacing: 0.12em;
  }

  :root.adm-portal .btn-primary,
  :root.adm-portal .btn-secondary,
  :root.adm-portal .btn-danger,
  :root.adm-portal .btn-ghost {
    border-radius: 10px;
    font-weight: 600;
  }
  :root.adm-portal .btn-primary {
    background-image: var(--adm-grad);
    color: #fff;
    box-shadow: 0 6px 20px -8px rgba(91, 63, 239, 0.65), inset 0 1px 0 rgba(255, 255, 255, 0.16);
  }
  :root.adm-portal .btn-primary:hover { filter: brightness(1.08); }
  :root.adm-portal .btn-secondary {
    border-color: var(--adm-line-2);
    background-color: var(--adm-surface-2);
    color: var(--adm-ink);
  }
  :root.adm-portal .btn-secondary:hover {
    border-color: var(--adm-line-3);
    background-color: var(--adm-surface-3);
  }
  :root.adm-portal .btn-ghost { color: var(--adm-muted); }
  :root.adm-portal .btn-ghost:hover { background-color: var(--adm-hover); color: var(--adm-ink); }
  :root.adm-portal .btn-danger { color: var(--adm-red); }

  :root.adm-portal .input {
    border-radius: 10px;
    border-color: var(--adm-line-2);
    background-color: var(--adm-ground-2);
    color: var(--adm-ink);
  }
  :root.adm-portal .input:focus {
    border-color: color-mix(in srgb, var(--adm-blue) 70%, transparent);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--adm-blue) 22%, transparent);
  }
  :root.adm-portal .label { color: var(--adm-muted); }

  :root.adm-portal .table-shell thead th {
    color: var(--adm-faint);
    padding: calc(var(--adm-cell-y) * 0.9) var(--adm-cell-x);
    letter-spacing: 0.08em;
    font-weight: 600;
    background: color-mix(in srgb, var(--adm-surface-2) 55%, transparent);
    position: sticky;
    top: 0;
    z-index: 1;
  }
  :root.adm-portal .table-shell tbody tr { border-color: var(--adm-line); }
  :root.adm-portal .table-shell tbody tr:hover { background-color: var(--adm-hover); }
  :root.adm-portal .table-shell tbody td { padding: var(--adm-cell-y) var(--adm-cell-x); }

  :root.adm-portal .kbd {
    border-color: var(--adm-line-2);
    background-color: var(--adm-surface-2);
    color: var(--adm-muted);
  }
  :root.adm-portal .divider { border-color: var(--adm-line); }
  :root.adm-portal .skeleton {
    background: linear-gradient(90deg, var(--adm-surface-2) 25%, var(--adm-surface-3) 37%, var(--adm-surface-2) 63%);
    background-size: 400% 100%;
    animation: adm-shimmer 1.4s ease infinite;
  }
  :root.adm-portal .grad-text {
    background-image: var(--adm-grad-aurora);
  }
}

/* ── LIGHT MODE: opacity-modified white utilities ───────────────────────── */
/* `bg-white/[0.04]`, `border-white/10`, `text-white/70` are lighteners tuned
   for a dark base; with `--color-white` flipped to ink they would turn into
   grey smudges. Same decoupling as the customer portal (app/globals.css),
   matched on the literal class text, excluding `.adm-dark` islands (chips and
   panels that stay dark in both themes). Unlayered + !important on purpose:
   they must beat the utility they retarget. */
:root.adm-portal[data-adm-theme="light"] [class*="bg-white/"]:not(.adm-dark, .adm-dark *) {
  background-color: color-mix(in srgb, var(--adm-ink) 5%, transparent) !important;
}
:root.adm-portal[data-adm-theme="light"] [class*="border-white/"]:not(.adm-dark, .adm-dark *) {
  border-color: var(--adm-line-2) !important;
}
:root.adm-portal[data-adm-theme="light"] [class*="text-white/"]:not(.adm-dark, .adm-dark *) {
  color: color-mix(in srgb, var(--adm-ink) 68%, transparent) !important;
}
:root.adm-portal[data-adm-theme="light"] [class*="divide-white/"]:not(.adm-dark, .adm-dark *) > * + * {
  border-color: var(--adm-line) !important;
}
/* A `text-white` on a saturated gradient/brand fill wants literal white in
   both themes (badges, solid buttons, avatar initials). */
:root.adm-portal[data-adm-theme="light"] [class*="bg-gradient-to-"][class~="text-white"],
:root.adm-portal[data-adm-theme="light"] [class~="bg-brand-500"][class~="text-white"],
:root.adm-portal[data-adm-theme="light"] [class~="bg-brand-600"][class~="text-white"],
:root.adm-portal[data-adm-theme="light"] [class~="bg-red-500"][class~="text-white"],
:root.adm-portal[data-adm-theme="light"] [class~="bg-emerald-500"][class~="text-white"] {
  color: #fff !important;
}
/* Native date/time pickers forced dark by `[color-scheme:dark]`. */
:root.adm-portal[data-adm-theme="light"] [class*="color-scheme:dark"]:not(.adm-dark, .adm-dark *) {
  color-scheme: light;
}
/* Pastel status text tuned for dark (text-emerald-300 etc.) — pull darker. */
:root.adm-portal[data-adm-theme="light"] [class~="text-emerald-300"],
:root.adm-portal[data-adm-theme="light"] [class~="text-emerald-400"] { color: #0a8a62 !important; }
:root.adm-portal[data-adm-theme="light"] [class~="text-amber-300"],
:root.adm-portal[data-adm-theme="light"] [class~="text-amber-400"],
:root.adm-portal[data-adm-theme="light"] [class~="text-amber-200"] { color: #a15f00 !important; }
:root.adm-portal[data-adm-theme="light"] [class~="text-red-300"],
:root.adm-portal[data-adm-theme="light"] [class~="text-red-400"] { color: #c22048 !important; }
:root.adm-portal[data-adm-theme="light"] [class~="text-cyan-300"],
:root.adm-portal[data-adm-theme="light"] [class~="text-sky-300"] { color: #087f97 !important; }

/* ══ SHELL ══════════════════════════════════════════════════════════════════
   Everything below is the admin shell's own classes (`adm-` prefix, used only
   by components/admin/shell/*). */
:root.adm-portal .adm-shell-root {
  display: flex;
  min-height: 100vh;
  color: var(--adm-ink-2);
}

/* sidebar */
:root.adm-portal .adm-rail {
  position: fixed;
  inset: 0 auto 0 0;
  z-index: 40;
  display: flex;
  flex-direction: column;
  width: 16rem;
  background: var(--adm-rail);
  border-right: 1px solid var(--adm-line);
  transform: translateX(-100%);
  transition: transform 0.22s cubic-bezier(.22, 1, .36, 1), width 0.18s ease;
}
:root.adm-portal .adm-rail[data-open="true"] { transform: none; box-shadow: 0 0 60px rgba(0, 0, 0, 0.45); }
@media (min-width: 1024px) {
  :root.adm-portal .adm-rail {
    position: sticky;
    top: 0;
    height: 100vh;
    transform: none;
    flex-shrink: 0;
  }
  :root.adm-portal .adm-rail[data-collapsed="true"] { width: 4.25rem; }
}
:root.adm-portal .adm-rail-head {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  height: 3.75rem;
  padding: 0 0.9rem 0 1rem;
  border-bottom: 1px solid var(--adm-line);
}
:root.adm-portal .adm-rail-nav {
  flex: 1;
  overflow-y: auto;
  padding: 0.6rem 0.6rem 1.25rem;
  scrollbar-width: thin;
}
:root.adm-portal .adm-group + .adm-group { margin-top: 0.85rem; }
:root.adm-portal .adm-group-head {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem;
  padding: 0.3rem 0.6rem;
  border-radius: 8px;
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--adm-faint);
}
:root.adm-portal .adm-group-head:hover { color: var(--adm-ink-2); }
:root.adm-portal .adm-group-head:focus-visible,
:root.adm-portal .adm-nav-row:focus-visible,
:root.adm-portal .adm-iconbtn:focus-visible,
:root.adm-portal .adm-more:focus-visible {
  outline: 2px solid var(--adm-cyan);
  outline-offset: 1px;
}
:root.adm-portal .adm-nav-row {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.65rem;
  min-height: 2.15rem;
  padding: 0.38rem 0.6rem;
  border-radius: 9px;
  font-size: 13.5px;
  font-weight: 520;
  color: var(--adm-ink-2);
  transition: background-color 0.12s ease, color 0.12s ease;
}
:root.adm-portal .adm-nav-row:hover { background: var(--adm-hover); color: var(--adm-ink); }
:root.adm-portal .adm-nav-row svg { flex-shrink: 0; color: var(--adm-muted); }
:root.adm-portal .adm-nav-row[aria-current="page"],
:root.adm-portal .adm-nav-row[data-active="true"] {
  background: var(--adm-active);
  color: var(--adm-ink);
}
:root.adm-portal .adm-nav-row[data-active="true"]::before {
  content: "";
  position: absolute;
  left: -0.6rem;
  top: 0.45rem;
  bottom: 0.45rem;
  width: 3px;
  border-radius: 0 3px 3px 0;
  background: var(--adm-grad-aurora);
}
:root.adm-portal .adm-nav-row[data-active="true"] svg { color: var(--adm-cyan); }
:root.adm-portal .adm-nav-sub {
  margin: 0.15rem 0 0.35rem 1.45rem;
  padding-left: 0.65rem;
  border-left: 1px solid var(--adm-line);
}
:root.adm-portal .adm-nav-sub .adm-nav-row { min-height: 1.85rem; font-size: 12.75px; padding: 0.25rem 0.55rem; color: var(--adm-muted); }
:root.adm-portal .adm-nav-sub .adm-nav-row[aria-current="page"] { color: var(--adm-ink); background: var(--adm-hover); }
:root.adm-portal .adm-count {
  margin-left: auto;
  display: inline-flex;
  min-width: 1.15rem;
  height: 1.15rem;
  align-items: center;
  justify-content: center;
  padding: 0 0.35rem;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 700;
  color: #fff;
  background: var(--adm-grad);
}
:root.adm-portal .adm-count[data-tone="red"] { background: #e23d63; }
:root.adm-portal .adm-dot {
  position: absolute;
  right: 0.35rem;
  top: 0.35rem;
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 999px;
  background: var(--adm-violet);
  box-shadow: 0 0 0 2px var(--adm-rail);
}
:root.adm-portal .adm-more {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 0.5rem;
  padding: 0.3rem 0.6rem;
  border-radius: 8px;
  font-size: 12px;
  color: var(--adm-faint);
}
:root.adm-portal .adm-more:hover { color: var(--adm-ink-2); background: var(--adm-hover); }
:root.adm-portal .adm-rail-foot {
  border-top: 1px solid var(--adm-line);
  padding: 0.6rem;
}
@media (min-width: 1024px) {
  :root.adm-portal .adm-rail[data-collapsed="true"] .adm-hide-collapsed { display: none !important; }
  :root.adm-portal .adm-rail[data-collapsed="true"] .adm-nav-row { justify-content: center; padding-inline: 0; }
  :root.adm-portal .adm-rail[data-collapsed="true"] .adm-nav-row[data-active="true"]::before { left: -0.6rem; }
  :root.adm-portal .adm-rail[data-collapsed="true"] .adm-rail-head { justify-content: center; padding: 0; }
}
:root.adm-portal .adm-rail:not([data-collapsed="true"]) .adm-show-collapsed { display: none; }
@media (max-width: 1023px) { :root.adm-portal .adm-show-collapsed { display: none; } }

:root.adm-portal .adm-scrim {
  position: fixed;
  inset: 0;
  z-index: 35;
  background: rgba(2, 5, 14, 0.55);
  backdrop-filter: blur(2px);
}

/* topbar */
:root.adm-portal .adm-topbar {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: 0.6rem;
  height: 3.75rem;
  padding: 0 1rem;
  border-bottom: 1px solid var(--adm-line);
  background: color-mix(in srgb, var(--adm-ground) 82%, transparent);
  backdrop-filter: blur(14px) saturate(1.2);
}
@media (min-width: 640px) { :root.adm-portal .adm-topbar { padding: 0 1.5rem; } }
:root.adm-portal .adm-search {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  width: 100%;
  max-width: 26rem;
  height: 2.35rem;
  padding: 0 0.75rem;
  border-radius: 10px;
  border: 1px solid var(--adm-line-2);
  background: var(--adm-surface);
  font-size: 13px;
  color: var(--adm-muted);
  transition: border-color 0.12s ease;
}
:root.adm-portal .adm-search:hover { border-color: var(--adm-line-3); }
:root.adm-portal .adm-iconbtn {
  position: relative;
  display: inline-flex;
  width: 2.35rem;
  height: 2.35rem;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  color: var(--adm-muted);
  transition: background-color 0.12s ease, color 0.12s ease;
}
:root.adm-portal .adm-iconbtn:hover { background: var(--adm-hover); color: var(--adm-ink); }
:root.adm-portal .adm-iconbtn[aria-pressed="true"] { color: var(--adm-cyan); }
:root.adm-portal .adm-badge-dot {
  position: absolute;
  top: 0.3rem;
  right: 0.3rem;
  min-width: 1rem;
  height: 1rem;
  padding: 0 0.25rem;
  border-radius: 999px;
  font-size: 9.5px;
  font-weight: 700;
  line-height: 1rem;
  text-align: center;
  color: #fff;
  background: #e23d63;
  box-shadow: 0 0 0 2px var(--adm-ground);
}
:root.adm-portal .adm-badge-dot[data-tone="brand"] { background: var(--adm-grad); }

/* popovers (alerts tray, account menu) */
:root.adm-portal .adm-pop {
  position: absolute;
  right: 0;
  top: calc(100% + 0.5rem);
  z-index: 50;
  width: min(24rem, calc(100vw - 2rem));
  overflow: hidden;
  border-radius: 14px;
  border: 1px solid var(--adm-line-2);
  background: var(--adm-surface);
  box-shadow: 0 24px 60px -20px rgba(0, 0, 0, 0.6);
  animation: adm-fade-up 0.14s ease;
}
:root.adm-portal .adm-pop-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--adm-line);
  font-size: 13px;
  font-weight: 650;
  color: var(--adm-ink);
}
:root.adm-portal .adm-pop-row {
  display: flex;
  gap: 0.7rem;
  padding: 0.7rem 1rem;
  border-bottom: 1px solid var(--adm-line);
  font-size: 13px;
}
:root.adm-portal a.adm-pop-row:hover { background: var(--adm-hover); }
:root.adm-portal .adm-tabs { display: flex; gap: 0.25rem; padding: 0.4rem 0.6rem; border-bottom: 1px solid var(--adm-line); }
:root.adm-portal .adm-tab {
  padding: 0.3rem 0.6rem;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 600;
  color: var(--adm-muted);
}
:root.adm-portal .adm-tab[aria-selected="true"] { background: var(--adm-active); color: var(--adm-ink); }

/* content */
:root.adm-portal .adm-main {
  width: 100%;
  margin: 0 auto;
  padding: 1.25rem 1rem 3rem;
  animation: adm-fade-up 0.2s ease;
}
@media (min-width: 640px) { :root.adm-portal .adm-main { padding: 1.5rem 1.75rem 3.5rem; } }
:root.adm-portal .adm-crumbs {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
  margin-bottom: 0.9rem;
  font-size: 12px;
  color: var(--adm-faint);
}
:root.adm-portal .adm-crumbs a:hover { color: var(--adm-ink); }
:root.adm-portal .adm-crumbs [aria-current="page"] { color: var(--adm-ink-2); }

