:root.adm-portal .adm-subtabs {
  display: flex;
  gap: 0.15rem;
  margin-bottom: 1.25rem;
  overflow-x: auto;
  border-bottom: 1px solid var(--adm-line);
  scrollbar-width: none;
}
:root.adm-portal .adm-subtabs::-webkit-scrollbar { display: none; }
:root.adm-portal .adm-subtab {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.45rem;
  padding: 0.55rem 0.8rem 0.65rem;
  font-size: 13px;
  font-weight: 560;
  color: var(--adm-muted);
  white-space: nowrap;
