:root.adm-portal .adm-subtab:hover { color: var(--adm-ink); }
:root.adm-portal .adm-subtab[aria-current="page"] { color: var(--adm-ink); }
:root.adm-portal .adm-subtab[aria-current="page"]::after {
  content: "";
  position: absolute;
  left: 0.6rem;
  right: 0.6rem;
  bottom: -1px;
