:root.adm-portal .adm-list > * + * { border-top: 1px solid var(--adm-line); }
:root.adm-portal .adm-live { width: 0.5rem; height: 0.5rem; border-radius: 999px; background: var(--adm-green); animation: adm-pulse 2s ease infinite; }

/* command palette */
:root.adm-portal .adm-cmdk-scrim {
  position: fixed;
