  padding: 12vh 1rem 1rem;
  background: rgba(2, 5, 14, 0.6);
  backdrop-filter: blur(3px);
}
:root.adm-portal .adm-cmdk {
  width: 100%;
  max-width: 40rem;
  overflow: hidden;
  border-radius: 16px;
  border: 1px solid var(--adm-line-2);
  background: var(--adm-surface);
  box-shadow: 0 40px 90px -30px rgba(0, 0, 0, 0.75);
  animation: adm-fade-up 0.14s ease;
}
:root.adm-portal .adm-cmdk input {
  width: 100%;
  height: 3.25rem;
  padding: 0 1rem 0 2.75rem;
  border: 0;
  border-bottom: 1px solid var(--adm-line);
  background: transparent;
  color: var(--adm-ink);
  font-size: 15px;
  outline: none;
}
:root.adm-portal .adm-cmdk-list { max-height: min(60vh, 28rem); overflow-y: auto; padding: 0.4rem; }
:root.adm-portal .adm-cmdk-sec { padding: 0.55rem 0.7rem 0.3rem; font-size: 10.5px; font-weight: 650; letter-spacing: 0.12em; text-transform: uppercase; color: var(--adm-faint); }
:root.adm-portal .adm-cmdk-opt {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  width: 100%;
  padding: 0.5rem 0.7rem;
  border-radius: 9px;
  font-size: 13.5px;
  color: var(--adm-ink-2);
  text-align: left;
}
:root.adm-portal .adm-cmdk-opt[aria-selected="true"] { background: var(--adm-active); color: var(--adm-ink); }
:root.adm-portal .adm-cmdk-opt small { color: var(--adm-faint); font-size: 11.5px; }

/* toasts */
:root.adm-portal .adm-toasts {
  position: fixed;
  z-index: 90;
  right: 1rem;
  bottom: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  width: min(22rem, calc(100vw - 2rem));
}
:root.adm-portal .adm-toast {
  display: flex;
  gap: 0.6rem;
  padding: 0.75rem 0.9rem;
  border-radius: 12px;
  border: 1px solid var(--adm-line-2);
  background: var(--adm-surface);
  box-shadow: 0 18px 50px -20px rgba(0, 0, 0, 0.6);
  font-size: 13px;
  color: var(--adm-ink);
  animation: adm-toast-in 0.18s ease;
}
:root.adm-portal .adm-toast[data-tone="error"] { border-color: color-mix(in srgb, var(--adm-red) 50%, transparent); }
:root.adm-portal .adm-toast[data-tone="success"] { border-color: color-mix(in srgb, var(--adm-green) 50%, transparent); }

/* avatar + logo */
:root.adm-portal .adm-avatar {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: 999px;
  font-weight: 700;
  color: #fff;
  background: var(--adm-grad);
  user-select: none;
}
:root.adm-portal .adm-avatar img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
:root.adm-portal .adm-wordmark {
  font-weight: 800;
  letter-spacing: 0.16em;
  font-size: 15px;
  color: var(--adm-ink);
}
:root.adm-portal .adm-env {
  border-radius: 6px;
  padding: 0.1rem 0.4rem;
  font-size: 9.5px;
  font-weight: 750;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--adm-cyan);
  border: 1px solid color-mix(in srgb, var(--adm-cyan) 35%, transparent);
  background: color-mix(in srgb, var(--adm-cyan) 8%, transparent);
}
:root.adm-portal[data-adm-theme="light"] .adm-logo-dark { display: none; }
:root.adm-portal:not([data-adm-theme="light"]) .adm-logo-light { display: none; }

@media (prefers-reduced-motion: reduce) {
  :root.adm-portal .adm-main,
  :root.adm-portal .adm-pop,
  :root.adm-portal .adm-cmdk,
  :root.adm-portal .adm-toast { animation: none; }
  :root.adm-portal .adm-rail { transition: none; }
}

