"use client";
/* eslint-disable @next/next/no-img-element -- brand PNGs + arbitrary avatar URLs; next/image would re-host them */

import { useState } from "react";

/**
 * Admin brand mark + avatar, both with graceful fallbacks.
 *
 * Why the fallbacks exist (2026-10-01): every `public/` asset — the logo, the
 * flags in the currency switcher, the favicon — returned HTTP 400 on the live
 * site between some deploys, because a build path that skipped
 * `scripts/promote-production.sh` left `.next/standalone/public` missing (fixed
 * at the source in scripts/postbuild-copy-geoip-data.sh). The admin chrome
 * rendered broken-image icons for the whole window. A missing asset must
 * degrade to something on-brand instead: the mark falls back to a gradient
 * "N" tile, an avatar to the person's initials.
 */
export function BrandMark({ size = 28 }: { size?: number }) {
  const [ok, setOk] = useState(true);
  if (!ok) {
    return (
      <span
        aria-hidden
        className="adm-avatar"
        style={{ width: size, height: size, borderRadius: 8, fontSize: size * 0.5 }}
      >
        N
      </span>
    );
  }
  return (
    <img
      src="/nx-mark.png"
      alt=""
      aria-hidden
      width={size}
      height={size}
      style={{ height: size, width: "auto" }}
      className="select-none object-contain"
      onError={() => setOk(false)}
      draggable={false}
    />
  );
}

/** Mark + typeset wordmark. Typeset (not the /logo.png lockup) so it reads in
 *  both themes — the lockup's letters are white-on-transparent. */
export function BrandLockup({ collapsed }: { collapsed?: boolean }) {
  return (
    <span className="flex min-w-0 items-center gap-2.5">
      <BrandMark size={26} />
      <span className={`adm-wordmark ${collapsed ? "adm-hide-collapsed" : ""}`}>NXEON</span>
      <span className={`adm-env ${collapsed ? "adm-hide-collapsed" : ""}`}>Ops</span>
    </span>
  );
}

export function initialsOf(name: string, email?: string): string {
  const src = (name || email || "?").trim();
  const parts = src.replace(/@.*/, "").split(/[\s._-]+/).filter(Boolean);
  if (parts.length === 0) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

const AVATAR_GRADS = [
  "linear-gradient(135deg,#3b6be8,#7b3fef)",
  "linear-gradient(135deg,#3edcf2,#3b6be8)",
  "linear-gradient(135deg,#7b3fef,#e04bd6)",
  "linear-gradient(135deg,#3fd89a,#3edcf2)",
  "linear-gradient(135deg,#f2b64b,#e04b7a)",
];

/** Deterministic gradient per seed so a person keeps "their" colour. */
export function avatarBackground(seed: string): string {
  let h = 0;
  for (let i = 0; i < seed.length; i++) h = (h * 31 + seed.charCodeAt(i)) >>> 0;
  return AVATAR_GRADS[h % AVATAR_GRADS.length];
}

export function Avatar({
  name,
  email,
  src,
  size = 32,
}: {
  name: string;
  email?: string;
  /** Optional photo URL (e.g. User.avatarUrl from Google sign-in). */
  src?: string | null;
  size?: number;
}) {
  const [failed, setFailed] = useState(false);
  return (
    <span
      className="adm-avatar"
      style={{ width: size, height: size, fontSize: Math.max(10, size * 0.38), background: avatarBackground(email || name) }}
      aria-hidden
    >
      {initialsOf(name, email)}
      {src && !failed && (
        <img src={src} alt="" referrerPolicy="no-referrer" loading="lazy" onError={() => setFailed(true)} />
      )}
    </span>
  );
}

