/** Serializable nav/alert shapes handed from app/admin/layout.tsx to the client shell. */

export type ShellNavChild = { label: string; href: string; badge?: number };

export type ShellNavItem = {
  key: string;
  label: string;
  /** Where the row links: the first accessible child, or the item's own href. */
  href: string;
  icon: string;
  badge?: number;
  more?: boolean;
  children?: ShellNavChild[];
};

export type ShellNavGroup = { key: string; label?: string; items: ShellNavItem[] };

/** A palette-reachable route (already RBAC-filtered server-side). */
export type ShellRoute = { label: string; href: string; group: string; parent?: string; keywords?: string };

export type ShellAlert = {
  id: string;
  tone: "red" | "amber" | "blue";
  title: string;
  detail?: string;
  href?: string;
  at?: string;
};

export type ShellNotification = {
  id: string;
  title: string;
  body?: string | null;
  href?: string | null;
  readAt: string | null;
  createdAt: string;
};

export type ShellUser = { name: string; email: string; role: string; avatarUrl?: string | null };

export type ShellUiState = {
  /** Group keys the user collapsed. */
  collapsedGroups: string[];
  /** Group keys whose "More" disclosure is open. */
  openMore: string[];
  /** Desktop rail collapsed to icons. */
  railCollapsed: boolean;
};

export const ADM_UI_COOKIE = "nx_adm_ui";

export function parseUiCookie(raw: string | undefined | null): ShellUiState {
  const empty: ShellUiState = { collapsedGroups: [], openMore: [], railCollapsed: false };
  if (!raw) return empty;
  try {
    const v = JSON.parse(decodeURIComponent(raw));
    const strs = (x: unknown) => (Array.isArray(x) ? x.filter((s): s is string => typeof s === "string" && s.length < 40).slice(0, 30) : []);
    return { collapsedGroups: strs(v.g), openMore: strs(v.m), railCollapsed: v.r === 1 };
  } catch {
    return empty;
  }
}

export function serializeUiCookie(s: ShellUiState): string {
  return encodeURIComponent(JSON.stringify({ g: s.collapsedGroups, m: s.openMore, r: s.railCollapsed ? 1 : 0 }));
}

