"use client";

import Link from "next/link";
import { useRef } from "react";
import { hrefMatches } from "@/lib/admin-nav";
import { AdmIcon } from "./icons";
import { BrandLockup } from "./Brand";
import type { ShellNavGroup, ShellNavItem, ShellUiState } from "./types";

/** Longest-matching item/child href for the current path, across the whole nav. */
export function activeHrefFor(groups: ShellNavGroup[], pathname: string): string | null {
  let best: string | null = null;
  for (const g of groups)
    for (const it of g.items)
      for (const h of [it.href, ...(it.children ?? []).map((c) => c.href)])
        if (hrefMatches(h, pathname) && (!best || h.length > best.length)) best = h;
  return best;
}

function itemIsActive(item: ShellNavItem, activeHref: string | null): boolean {
  if (!activeHref) return false;
  return item.href === activeHref || (item.children ?? []).some((c) => c.href === activeHref);
}

const fmtCount = (n: number) => (n > 99 ? "99+" : String(n));

/**
 * The admin rail: task-oriented collapsible groups, an optional "More"
 * disclosure per group for rarely-used pages, nested children for the active
 * item, attention counts that roll up onto a collapsed group's header, a
 * desktop icon-only mode, and an off-canvas drawer below `lg`.
 *
 * Keyboard: every control is a real <button>/<a>; ArrowUp/ArrowDown move
 * between rows (Home/End jump to the ends) so the 30-odd rows don't need 30
 * Tabs; Escape closes the mobile drawer (handled by the shell).
 */
export function Sidebar({
  groups,
  pathname,
  ui,
  onToggleGroup,
  onToggleMore,
  onToggleRail,
  open,
  isDesktop,
  onClose,
}: {
  groups: ShellNavGroup[];
  pathname: string;
  ui: ShellUiState;
  onToggleGroup: (key: string) => void;
  onToggleMore: (key: string) => void;
  onToggleRail: () => void;
  open: boolean;
  isDesktop: boolean;
  onClose: () => void;
}) {
  const navRef = useRef<HTMLElement>(null);
  const activeHref = activeHrefFor(groups, pathname);
  const collapsed = ui.railCollapsed && isDesktop;
  const hidden = !isDesktop && !open;

  function onKeyDown(e: React.KeyboardEvent) {
    if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(e.key)) return;
    const rows = [...(navRef.current?.querySelectorAll<HTMLElement>("[data-nav-row]") ?? [])].filter(
      (el) => el.offsetParent !== null,
    );
    if (rows.length === 0) return;
    const i = rows.indexOf(document.activeElement as HTMLElement);
    let next = i;
    if (e.key === "ArrowDown") next = i < 0 ? 0 : Math.min(rows.length - 1, i + 1);
    if (e.key === "ArrowUp") next = i < 0 ? rows.length - 1 : Math.max(0, i - 1);
    if (e.key === "Home") next = 0;
    if (e.key === "End") next = rows.length - 1;
    e.preventDefault();
    rows[next]?.focus();
  }

  return (
    <aside
      id="adm-rail"
      className="adm-rail"
      data-open={open ? "true" : "false"}
      data-collapsed={collapsed ? "true" : "false"}
      aria-label="Admin navigation"
      inert={hidden}
      aria-hidden={hidden || undefined}
    >
      <div className="adm-rail-head">
        <Link href="/admin" className="flex min-w-0 items-center" aria-label="Nxeon Ops — command center" data-nav-row>
          <BrandLockup collapsed={collapsed} />
        </Link>
        <button type="button" className="adm-iconbtn ml-auto lg:hidden" aria-label="Close menu" onClick={onClose}>
          <AdmIcon name="close" />
        </button>
      </div>

      <nav ref={navRef} className="adm-rail-nav" onKeyDown={onKeyDown}>
        {groups.map((g) => {
          const groupCollapsed = !!g.label && ui.collapsedGroups.includes(g.key) && !collapsed;
          const primary = g.items.filter((i) => !i.more);
          const extra = g.items.filter((i) => i.more);
          // A demoted page you're currently on is shown regardless, so the
          // highlighted row never disappears behind a closed "More".
          const moreOpen = ui.openMore.includes(g.key) || extra.some((i) => itemIsActive(i, activeHref)) || collapsed;
          const total = g.items.reduce((s, i) => s + (i.badge ?? 0), 0);
          const regionId = `adm-group-${g.key}`;
          return (
            <div key={g.key} className="adm-group">
              {g.label && (
                <button
                  type="button"
                  className={`adm-group-head adm-hide-collapsed`}
                  aria-expanded={!groupCollapsed}
                  aria-controls={regionId}
                  onClick={() => onToggleGroup(g.key)}
                  data-nav-row
                >
                  <span className="flex items-center gap-1.5">
                    {g.label}
                    {groupCollapsed && total > 0 && <span className="adm-count" style={{ marginLeft: 4 }}>{fmtCount(total)}</span>}
                  </span>
                  <span style={{ transform: groupCollapsed ? "rotate(-90deg)" : undefined, transition: "transform .15s" }}>
                    <AdmIcon name="chevron" size={12} strokeWidth={2.4} />
                  </span>
                </button>
              )}
              {g.label && collapsed && <div className="mx-3 my-2 h-px" style={{ background: "var(--adm-line)" }} aria-hidden />}
              <div id={regionId} hidden={groupCollapsed} className="mt-0.5 space-y-0.5">
                {primary.map((it) => (
                  <NavRow key={it.key} item={it} activeHref={activeHref} collapsed={collapsed} onNavigate={onClose} />
                ))}
                {extra.length > 0 && !collapsed && (
                  <button
                    type="button"
                    className="adm-more"
                    aria-expanded={moreOpen}
                    onClick={() => onToggleMore(g.key)}
                    data-nav-row
                  >
                    <span style={{ transform: moreOpen ? undefined : "rotate(-90deg)", transition: "transform .15s", display: "inline-flex" }}>
                      <AdmIcon name="chevron" size={12} strokeWidth={2.2} />
                    </span>
                    {moreOpen ? "Less" : `More (${extra.length})`}
                  </button>
                )}
                {moreOpen &&
                  extra.map((it) => (
                    <NavRow key={it.key} item={it} activeHref={activeHref} collapsed={collapsed} onNavigate={onClose} />
                  ))}
              </div>
            </div>
          );
        })}
      </nav>

      <div className="adm-rail-foot hidden lg:block">
        <button
          type="button"
          className="adm-nav-row w-full"
          onClick={onToggleRail}
          aria-pressed={collapsed}
          title={collapsed ? "Expand sidebar" : "Collapse sidebar"}
          data-nav-row
        >
          <span style={{ transform: collapsed ? "rotate(180deg)" : undefined, display: "inline-flex" }}>
            <AdmIcon name="collapse" size={16} />
          </span>
          <span className="adm-hide-collapsed text-[12.5px]">Collapse sidebar</span>
          <span className="kbd adm-hide-collapsed ml-auto">[</span>
        </button>
      </div>
    </aside>
  );
}

function NavRow({
  item,
  activeHref,
  collapsed,
  onNavigate,
}: {
  item: ShellNavItem;
  activeHref: string | null;
  collapsed: boolean;
  onNavigate: () => void;
}) {
  const active = itemIsActive(item, activeHref);
  const kids = item.children && item.children.length > 1 ? item.children : null;
  return (
    <div>
      <Link
        href={item.href}
        onClick={onNavigate}
        className="adm-nav-row"
        data-active={active ? "true" : undefined}
        aria-current={activeHref === item.href ? "page" : undefined}
        title={collapsed ? item.label : undefined}
        data-nav-row
      >
        <AdmIcon name={item.icon} size={17} />
        <span className="adm-hide-collapsed min-w-0 truncate">{item.label}</span>
        {!!item.badge && <span className="adm-count adm-hide-collapsed">{fmtCount(item.badge)}</span>}
        {!!item.badge && collapsed && <span className="adm-dot" aria-hidden />}
        {collapsed && <span className="sr-only">{item.label}{item.badge ? `, ${item.badge} waiting` : ""}</span>}
      </Link>
      {active && kids && !collapsed && (
        <div className="adm-nav-sub">
          {kids.map((c) => (
            <Link
              key={c.href}
              href={c.href}
              onClick={onNavigate}
              className="adm-nav-row"
              aria-current={activeHref === c.href ? "page" : undefined}
              data-nav-row
            >
              <span className="min-w-0 truncate">{c.label}</span>
              {!!c.badge && <span className="adm-count">{fmtCount(c.badge)}</span>}
            </Link>
          ))}
        </div>
      )}
    </div>
  );
}

