import { NextRequest, NextResponse } from "next/server";
import type { Prisma } from "@prisma/client";
import { realUser } from "@/lib/auth";
import { canAccess, isStaff, type Area } from "@/lib/rbac";
import { db } from "@/lib/db";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * GLOBAL ADMIN SEARCH — powers the admin ⌘K palette
 * (components/admin/shell/CommandPalette.tsx). READ-ONLY.
 *
 * GET /api/admin/search?q=… → { results: [{ type, id, label, sub, href }] }
 *
 * Searches, each block gated by the caller's RBAC area (lib/rbac.ts) so a
 * SUPPORT/BILLING account never receives rows from an area it can't open:
 *   • users     (clients)        — email, name, exact id
 *   • servers   (fleet)          — hostname, name, label, subdomain, IP
 *                                  (NAT or dedicated), previous hostname,
 *                                  exact vmid, exact id
 *   • free MC / web hosting (fleet) — subdomain/name, domain/username
 *   • tickets   (supportTickets) — subject, exact id, customer email
 *   • invoices  (billing)        — number ("123", "#123", "INV-123"),
 *                                  description, customer email
 *   • emails    (platform)       — recipient address, subject
 *
 * Staff only, by the real signed-in account (never the impersonated one).
 * Every block fails soft so one bad table can't blank the palette. The
 * response is `private, no-store`: it carries other customers' PII and must
 * never be replayed from a shared cache keyed on the URL.
 */

type Result = { type: string; id: string; label: string; sub?: string; href: string };

const soft = <T,>(p: Promise<T>, fallback: T): Promise<T> => p.catch(() => fallback);

export async function GET(req: NextRequest) {
  const user = await realUser();
  if (!user || !isStaff(user.role)) {
    return NextResponse.json({ results: [] }, { status: 401, headers: NO_STORE_HEADERS });
  }
  // Bounded input: the palette never needs more, and a giant `contains`
  // pattern is pointless work for Postgres.
  const q = (req.nextUrl.searchParams.get("q") ?? "").trim().slice(0, 80);
  if (q.length < 2) return NextResponse.json({ results: [] }, { headers: NO_STORE_HEADERS });

  const can = (a: Area) => canAccess(user.role, a);
  const like = { contains: q, mode: "insensitive" as const };
  const digits = /^#?(?:inv-?)?(\d{1,9})$/i.exec(q)?.[1];
  const num = digits ? Number(digits) : null;
  const looksLikeId = /^c[a-z0-9]{20,30}$/i.test(q);
  const none = Promise.resolve([] as never[]);

  const serverWhere: Prisma.ServerWhereInput = {
    OR: [
      { hostname: like },
      { name: like },
      { label: like },
      { subdomain: like },
      { ipAddress: { startsWith: q } },
      { previousHostnames: { has: q.toLowerCase() } },
      { dedicatedIp: { address: { startsWith: q } } },
      ...(num !== null && num < 2_147_483_647 ? [{ vmid: num }] : []),
      ...(looksLikeId ? [{ id: q }] : []),
    ],
  };

  const [users, servers, freemc, hosting, tickets, invoices, emails] = await Promise.all([
    can("clients")
      ? soft(
          db.user.findMany({
            where: { OR: [{ email: like }, { name: like }, ...(looksLikeId ? [{ id: q }] : [])] },
            select: { id: true, email: true, name: true, role: true, suspended: true },
            orderBy: { createdAt: "desc" },
            take: 6,
          }),
          [],
        )
      : none,
    can("fleet")
      ? soft(
          db.server.findMany({
            where: serverWhere,
            select: {
              id: true, hostname: true, name: true, label: true, status: true, vmid: true, ipAddress: true,
              subdomain: true, gameVariant: true, user: { select: { email: true } }, node: { select: { name: true } },
            },
            orderBy: { createdAt: "desc" },
            take: 8,
          }),
          [],
        )
      : none,
    can("fleet")
      ? soft(
          db.freeMinecraftServer.findMany({
            where: { OR: [{ subdomain: like }, { name: like }] },
            select: { id: true, subdomain: true, name: true, status: true, user: { select: { email: true } } },
            take: 4,
          }),
          [],
        )
      : none,
    can("fleet")
      ? soft(
          db.hostingAccount.findMany({
            where: { OR: [{ primaryDomain: like }, { username: like }] },
            select: { id: true, primaryDomain: true, username: true, status: true, user: { select: { email: true } } },
            take: 4,
          }),
          [],
        )
      : none,
    can("supportTickets")
      ? soft(
          db.ticket.findMany({
            where: { OR: [{ subject: like }, { user: { email: like } }, ...(looksLikeId ? [{ id: q }] : [])] },
            select: { id: true, subject: true, status: true, user: { select: { email: true } } },
            orderBy: { updatedAt: "desc" },
            take: 6,
          }),
          [],
        )
      : none,
    can("billing")
      ? soft(
          db.invoice.findMany({
            where: {
              OR: [
                ...(num !== null && num < 2_147_483_647 ? [{ number: num }] : []),
                { description: like },
                { user: { email: like } },
              ],
            },
            select: { id: true, number: true, amountCents: true, status: true, user: { select: { email: true } } },
            orderBy: { createdAt: "desc" },
            take: 6,
          }),
          [],
        )
      : none,
    can("platform")
      ? soft(
          db.emailLog.findMany({
            where: { OR: [{ toEmail: like }, { subject: like }] },
            select: { id: true, toEmail: true, subject: true, status: true, userId: true, createdAt: true },
            orderBy: { createdAt: "desc" },
            take: 5,
          }),
          [],
        )
      : none,
  ]);

  const results: Result[] = [];
  for (const u of users)
    results.push({
      type: "user", id: u.id, label: u.name || u.email,
      sub: `${u.email}${u.role !== "CUSTOMER" ? ` · ${u.role.toLowerCase()}` : ""}${u.suspended ? " · suspended" : ""}`,
      href: `/admin/users/${u.id}`,
    });
  for (const s of servers)
    results.push({
      type: s.gameVariant ? "game" : "server", id: s.id, label: s.label || s.hostname,
      sub: [s.status.toLowerCase(), s.vmid != null ? `vmid ${s.vmid}` : null, s.ipAddress, s.subdomain, s.node?.name, s.user.email]
        .filter(Boolean).join(" · "),
      href: `/admin/servers/${s.id}`,
    });
  for (const f of freemc)
    results.push({
      type: "freemc", id: f.id, label: f.name || f.subdomain, sub: `free Minecraft · ${f.subdomain} · ${f.user.email}`,
      href: `/admin/free-minecraft`,
    });
  for (const h of hosting)
    results.push({
      type: "hosting", id: h.id, label: h.primaryDomain, sub: `web hosting · ${h.username} · ${h.user.email}`,
      href: `/admin/hosting`,
    });
  for (const t of tickets)
    results.push({
      type: "ticket", id: t.id, label: t.subject, sub: `${t.status.toLowerCase().replace(/_/g, " ")} · ${t.user.email}`,
      href: `/admin/support/${t.id}`,
    });
  for (const i of invoices)
    results.push({
      type: "invoice", id: i.id, label: `Invoice #${i.number}`,
      sub: `$${(i.amountCents / 100).toFixed(2)} · ${i.status.toLowerCase()} · ${i.user.email}`,
      href: `/admin/invoices/${i.id}`,
    });
  for (const e of emails)
    results.push({
      type: "email", id: e.id, label: e.subject, sub: `${e.toEmail} · ${e.status} · ${e.createdAt.toISOString().slice(0, 10)}`,
      href: e.userId ? `/admin/users/${e.userId}` : `/admin/mail`,
    });

  return NextResponse.json({ results }, { headers: NO_STORE_HEADERS });
}

