import { NextResponse } from "next/server";
import { realUser } from "@/lib/auth";
import { isStaff } from "@/lib/rbac";
import { db } from "@/lib/db";
import { loadShellAlerts } from "@/lib/admin/shell-alerts";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * READ-ONLY feed for the admin shell's alerts tray
 * (components/admin/shell/AlertsTray.tsx), polled while an admin tab is open.
 * Same data the layout renders on first paint — see lib/admin/shell-alerts.ts.
 *
 * GET /api/admin/alerts → { alerts: ShellAlert[], notifications: ShellNotification[] }
 */
export async function GET() {
  const user = await realUser();
  if (!user || !isStaff(user.role)) {
    return NextResponse.json({ alerts: [], notifications: [] }, { status: 401, headers: NO_STORE_HEADERS });
  }
  const [alerts, notifications] = await Promise.all([
    loadShellAlerts(user.role),
    db.notification
      .findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 15 })
      .catch(() => []),
  ]);
  return NextResponse.json(
    {
      alerts,
      notifications: notifications.map((n) => ({
        id: n.id,
        title: n.title,
        body: n.body,
        href: n.href,
        readAt: n.readAt ? n.readAt.toISOString() : null,
        createdAt: n.createdAt.toISOString(),
      })),
    },
    { headers: NO_STORE_HEADERS },
  );
}

