"use client";

import Link from "next/link";
import { useEffect, useRef, useState, useTransition } from "react";
import { markNotificationsRead } from "@/lib/actions-account";
import { AdmIcon } from "./icons";
import type { ShellAlert, ShellNotification } from "./types";

const POLL_MS = 60_000;

function ago(iso?: string): string {
  if (!iso) return "";
  const s = Math.max(0, Math.floor((Date.now() - Date.parse(iso)) / 1000));
  if (s < 60) return "just now";
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  return `${Math.floor(s / 86400)}d ago`;
}

/**
 * Top-bar bell. Two tabs:
 *   Alerts        — live operational items (failed jobs, node capacity alerts,
 *                   tickets awaiting staff, unread chats, abuse, migrations),
 *                   from lib/admin/shell-alerts.ts. Not dismissable: an item
 *                   disappears when the underlying condition clears.
 *   Notifications — the account's own Notification rows; opening the tab marks
 *                   them read (same server action the old shell used).
 * Seeded from the server render, refreshed by polling /api/admin/alerts while
 * the tab is visible.
 */
export function AlertsTray({
  initialAlerts,
  initialNotifications,
}: {
  initialAlerts: ShellAlert[];
  initialNotifications: ShellNotification[];
}) {
  const [open, setOpen] = useState(false);
  const [tab, setTab] = useState<"alerts" | "notifications">("alerts");
  const [alerts, setAlerts] = useState(initialAlerts);
  const [notifs, setNotifs] = useState(initialNotifications);
  const [markedAt, setMarkedAt] = useState<number | null>(null);
  const [, startTransition] = useTransition();
  const wrapRef = useRef<HTMLDivElement>(null);
  const btnRef = useRef<HTMLButtonElement>(null);

  useEffect(() => setAlerts(initialAlerts), [initialAlerts]);
  useEffect(() => setNotifs(initialNotifications), [initialNotifications]);

  useEffect(() => {
    let alive = true;
    const load = () => {
      if (document.visibilityState !== "visible") return;
      fetch("/api/admin/alerts", { cache: "no-store" })
        .then((r) => (r.ok ? r.json() : null))
        .then((d) => {
          if (!alive || !d) return;
          if (Array.isArray(d.alerts)) setAlerts(d.alerts);
          if (Array.isArray(d.notifications)) setNotifs(d.notifications);
        })
        .catch(() => {});
    };
    const id = setInterval(load, POLL_MS);
    return () => {
      alive = false;
      clearInterval(id);
    };
  }, []);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        setOpen(false);
        btnRef.current?.focus();
      }
    };
    const onDown = (e: MouseEvent) => {
      if (!wrapRef.current?.contains(e.target as Node)) setOpen(false);
    };
    window.addEventListener("keydown", onKey);
    window.addEventListener("mousedown", onDown);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("mousedown", onDown);
    };
  }, [open]);

  const unread = notifs.filter((n) => !n.readAt && !(markedAt && Date.parse(n.createdAt) <= markedAt)).length;
  const redCount = alerts.filter((a) => a.tone === "red").length;
  const total = alerts.length + unread;

  function showNotifications() {
    setTab("notifications");
    if (unread > 0) {
      setMarkedAt(Date.now());
      startTransition(() => markNotificationsRead());
    }
  }

  return (
    <div ref={wrapRef} className="relative">
      <button
        ref={btnRef}
        type="button"
        className="adm-iconbtn"
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-label={total > 0 ? `Alerts and notifications, ${total} items` : "Alerts and notifications"}
        onClick={() => setOpen((v) => !v)}
      >
        <AdmIcon name="bell" />
        {total > 0 && (
          <span className="adm-badge-dot" data-tone={redCount > 0 ? undefined : "brand"}>
            {total > 99 ? "99+" : total}
          </span>
        )}
      </button>
      {open && (
        <div className="adm-pop" role="dialog" aria-label="Alerts and notifications">
          <div className="adm-tabs" role="tablist">
            <button type="button" role="tab" className="adm-tab" aria-selected={tab === "alerts"} onClick={() => setTab("alerts")}>
              Alerts{alerts.length ? ` · ${alerts.length}` : ""}
            </button>
            <button type="button" role="tab" className="adm-tab" aria-selected={tab === "notifications"} onClick={showNotifications}>
              Notifications{unread ? ` · ${unread}` : ""}
            </button>
          </div>
          <div className="max-h-[26rem] overflow-y-auto" role="tabpanel">
            {tab === "alerts" ? (
              alerts.length === 0 ? (
                <p className="px-4 py-10 text-center text-[13px]" style={{ color: "var(--adm-muted)" }}>
                  Nothing needs attention right now.
                </p>
              ) : (
                alerts.map((a) => {
                  const body = (
                    <>
                      <span
                        className="mt-1.5 h-2 w-2 shrink-0 rounded-full"
                        style={{ background: a.tone === "red" ? "var(--adm-red)" : a.tone === "amber" ? "var(--adm-amber)" : "var(--adm-blue)" }}
                        aria-hidden
                      />
                      <span className="min-w-0 flex-1">
                        <span className="block font-semibold" style={{ color: "var(--adm-ink)" }}>{a.title}</span>
                        {a.detail && <span className="mt-0.5 block truncate text-[12px]" style={{ color: "var(--adm-muted)" }}>{a.detail}</span>}
                      </span>
                      {a.at && <span className="shrink-0 text-[11px]" style={{ color: "var(--adm-faint)" }}>{ago(a.at)}</span>}
                    </>
                  );
                  return a.href ? (
                    <Link key={a.id} href={a.href} className="adm-pop-row" onClick={() => setOpen(false)}>{body}</Link>
                  ) : (
                    <div key={a.id} className="adm-pop-row">{body}</div>
                  );
                })
              )
            ) : notifs.length === 0 ? (
              <p className="px-4 py-10 text-center text-[13px]" style={{ color: "var(--adm-muted)" }}>All caught up.</p>
            ) : (
              notifs.map((n) => {
                const isUnread = !n.readAt && !(markedAt && Date.parse(n.createdAt) <= markedAt);
                const body = (
                  <>
                    <span className="mt-1.5 h-2 w-2 shrink-0 rounded-full" style={{ background: isUnread ? "var(--adm-violet)" : "transparent" }} aria-hidden />
                    <span className="min-w-0 flex-1">
                      <span className={`block ${isUnread ? "font-semibold" : ""}`} style={{ color: "var(--adm-ink)" }}>{n.title}</span>
                      {n.body && <span className="mt-0.5 block text-[12px]" style={{ color: "var(--adm-muted)" }}>{n.body}</span>}
                      <span className="mt-1 block text-[11px]" style={{ color: "var(--adm-faint)" }}>{ago(n.createdAt)}</span>
                    </span>
                  </>
                );
                return n.href ? (
                  <Link key={n.id} href={n.href} className="adm-pop-row" onClick={() => setOpen(false)}>{body}</Link>
                ) : (
                  <div key={n.id} className="adm-pop-row">{body}</div>
                );
              })
            )}
          </div>
        </div>
      )}
    </div>
  );
}

