"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { AdmIcon } from "./icons";
import type { ShellRoute } from "./types";

type SearchHit = { type: string; id: string; label: string; sub?: string; href: string };
type Option =
  | { kind: "route"; key: string; label: string; sub?: string; href: string; icon: string; section: string }
  | { kind: "action"; key: string; label: string; sub?: string; run: () => void; icon: string; section: string }
  | { kind: "hit"; key: string; label: string; sub?: string; href: string; icon: string; section: string };

const HIT_SECTION: Record<string, [string, string]> = {
  user: ["Clients", "user"],
  server: ["Servers", "server"],
  game: ["Servers", "game"],
  freemc: ["Servers", "game"],
  hosting: ["Servers", "globe"],
  ticket: ["Tickets", "ticket"],
  invoice: ["Invoices", "invoice"],
  email: ["Emails", "mail"],
};

export type PaletteAction = { key: string; label: string; sub?: string; icon: string; run: () => void; keywords?: string };

/** Subsequence-ish score: exact prefix > word prefix > substring > none. */
function score(hay: string, q: string): number {
  const h = hay.toLowerCase();
  if (h.startsWith(q)) return 3;
  if (h.split(/[\s/&·-]+/).some((w) => w.startsWith(q))) return 2;
  if (h.includes(q)) return 1;
  return 0;
}

/**
 * ⌘K / Ctrl+K (or "/" outside a text field) command palette for the admin
 * shell: every page the role can reach (from lib/admin-nav.ts, RBAC-filtered
 * server-side), quick actions, and debounced GLOBAL SEARCH across clients,
 * servers (name/hostname/subdomain/IP/vmid), tickets, invoices and sent emails
 * via GET /api/admin/search — which applies the same RBAC per entity.
 *
 * A11y: role=dialog + aria-modal, a combobox input that owns a listbox,
 * aria-activedescendant for the highlighted option, Arrow/Home/End/Enter/Esc,
 * Tab trapped on the input, focus restored to the opener on close.
 */
export function CommandPalette({
  routes,
  actions,
  open,
  onOpenChange,
}: {
  routes: ShellRoute[];
  actions: PaletteAction[];
  open: boolean;
  onOpenChange: (v: boolean) => void;
}) {
  const router = useRouter();
  const [q, setQ] = useState("");
  const [hits, setHits] = useState<SearchHit[]>([]);
  const [searching, setSearching] = useState(false);
  const [active, setActive] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const restoreFocus = useRef<HTMLElement | null>(null);
  const reqId = useRef(0);

  // Global shortcuts.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement | null;
      const typing = !!t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName));
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        e.preventDefault();
        onOpenChange(!open);
      } else if (!open && e.key === "/" && !typing && !e.metaKey && !e.ctrlKey && !e.altKey) {
        e.preventDefault();
        onOpenChange(true);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, onOpenChange]);

  useEffect(() => {
    if (open) {
      restoreFocus.current = (document.activeElement as HTMLElement) ?? null;
      setQ("");
      setHits([]);
      setActive(0);
      setTimeout(() => inputRef.current?.focus(), 20);
    } else if (restoreFocus.current) {
      restoreFocus.current.focus?.();
      restoreFocus.current = null;
    }
  }, [open]);

  // Debounced global search.
  useEffect(() => {
    const query = q.trim();
    if (query.length < 2) {
      setHits([]);
      setSearching(false);
      return;
    }
    setSearching(true);
    const id = ++reqId.current;
    const t = setTimeout(async () => {
      try {
        const res = await fetch(`/api/admin/search?q=${encodeURIComponent(query)}`, { cache: "no-store" });
        const json = res.ok ? await res.json() : { results: [] };
        if (id === reqId.current) setHits(Array.isArray(json.results) ? json.results : []);
      } catch {
        if (id === reqId.current) setHits([]);
      } finally {
        if (id === reqId.current) setSearching(false);
      }
    }, 200);
    return () => clearTimeout(t);
  }, [q]);

  const options: Option[] = useMemo(() => {
    const query = q.trim().toLowerCase();
    const out: Option[] = [];
    const routeOpts = routes
      .map((r) => ({ r, s: query ? Math.max(score(r.label, query), score(`${r.parent ?? ""} ${r.group} ${r.keywords ?? ""}`, query) && 1) : 1 }))
      .filter((x) => x.s > 0)
      .sort((a, b) => b.s - a.s)
      .slice(0, query ? 8 : 10)
      .map(({ r }) => ({
        kind: "route" as const,
        key: `r:${r.href}`,
        label: r.parent && r.parent !== r.label ? `${r.parent} › ${r.label}` : r.label,
        sub: r.group,
        href: r.href,
        icon: "chevronRight",
        section: "Go to",
      }));
    const actionOpts = actions
      .filter((a) => !query || score(`${a.label} ${a.keywords ?? ""}`, query) > 0)
      .slice(0, query ? 5 : 6)
      .map((a) => ({ kind: "action" as const, key: `a:${a.key}`, label: a.label, sub: a.sub, run: a.run, icon: a.icon, section: "Actions" }));
    const hitOpts = hits.map((h) => {
      const [section, icon] = HIT_SECTION[h.type] ?? ["Results", "search"];
      return { kind: "hit" as const, key: `h:${h.type}:${h.id}`, label: h.label, sub: h.sub, href: h.href, icon, section };
    });
    // Search hits lead once the query is specific enough to have produced any.
    if (query.length >= 2) out.push(...hitOpts, ...routeOpts, ...actionOpts);
    else out.push(...routeOpts, ...actionOpts);
    return out;
  }, [q, routes, actions, hits]);

  useEffect(() => setActive(0), [q, hits.length]);
  useEffect(() => {
    listRef.current?.querySelector<HTMLElement>(`[data-idx="${active}"]`)?.scrollIntoView({ block: "nearest" });
  }, [active]);

  const choose = useCallback(
    (o: Option | undefined) => {
      if (!o) return;
      onOpenChange(false);
      if (o.kind === "action") o.run();
      else router.push(o.href);
    },
    [onOpenChange, router],
  );

  if (!open) return null;

  let lastSection = "";
  return (
    <div className="adm-cmdk-scrim" onMouseDown={(e) => e.target === e.currentTarget && onOpenChange(false)}>
      <div className="adm-cmdk" role="dialog" aria-modal="true" aria-label="Command palette">
        <div className="relative">
          <span className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2" style={{ color: "var(--adm-muted)" }}>
            <AdmIcon name="search" size={17} />
          </span>
          <input
            ref={inputRef}
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="Search clients, servers, IPs, vmids, tickets, invoices… or jump to a page"
            role="combobox"
            aria-expanded="true"
            aria-controls="adm-cmdk-list"
            aria-activedescendant={options[active] ? `adm-opt-${active}` : undefined}
            aria-autocomplete="list"
            spellCheck={false}
            onKeyDown={(e) => {
              if (e.key === "ArrowDown") { e.preventDefault(); setActive((i) => Math.min(options.length - 1, i + 1)); }
              else if (e.key === "ArrowUp") { e.preventDefault(); setActive((i) => Math.max(0, i - 1)); }
              else if (e.key === "Home") { e.preventDefault(); setActive(0); }
              else if (e.key === "End") { e.preventDefault(); setActive(options.length - 1); }
              else if (e.key === "Enter") { e.preventDefault(); choose(options[active]); }
              else if (e.key === "Escape") { e.preventDefault(); onOpenChange(false); }
              else if (e.key === "Tab") e.preventDefault();
            }}
          />
          {searching && (
            <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[11px]" style={{ color: "var(--adm-faint)" }}>
              searching…
            </span>
          )}
        </div>
        <div ref={listRef} id="adm-cmdk-list" role="listbox" className="adm-cmdk-list" aria-label="Results">
          {options.length === 0 ? (
            <p className="px-4 py-8 text-center text-[13px]" style={{ color: "var(--adm-muted)" }}>
              {searching ? "Searching…" : `No matches for “${q}”.`}
            </p>
          ) : (
            options.map((o, i) => {
              const head = o.section !== lastSection ? o.section : null;
              lastSection = o.section;
              return (
                <div key={o.key}>
                  {head && <div className="adm-cmdk-sec" role="presentation">{head}</div>}
                  <button
                    type="button"
                    id={`adm-opt-${i}`}
                    data-idx={i}
                    role="option"
                    aria-selected={i === active}
                    tabIndex={-1}
                    className="adm-cmdk-opt"
                    onMouseMove={() => setActive(i)}
                    onClick={() => choose(o)}
                  >
                    <span style={{ color: "var(--adm-muted)", display: "inline-flex" }}><AdmIcon name={o.icon} size={16} /></span>
                    <span className="min-w-0 flex-1">
                      <span className="block truncate">{o.label}</span>
                      {o.sub && <small className="block truncate">{o.sub}</small>}
                    </span>
                    {i === active && <span style={{ color: "var(--adm-faint)", display: "inline-flex" }}><AdmIcon name="enter" size={14} /></span>}
                  </button>
                </div>
              );
            })
          )}
        </div>
        <div className="flex items-center gap-3 border-t px-4 py-2 text-[11px]" style={{ borderColor: "var(--adm-line)", color: "var(--adm-faint)" }}>
          <span><span className="kbd">↑↓</span> move</span>
          <span><span className="kbd">↵</span> open</span>
          <span><span className="kbd">esc</span> close</span>
          <span className="ml-auto">Search covers clients, servers, tickets, invoices &amp; emails you can access</span>
        </div>
      </div>
    </div>
  );
}

