"use client";

import { createContext, useCallback, useContext, useEffect, useRef, useState } from "react";
import { AdmIcon } from "./icons";

export type ToastTone = "info" | "success" | "error";
type Toast = { id: number; title: string; body?: string; tone: ToastTone };

const Ctx = createContext<(t: { title: string; body?: string; tone?: ToastTone }) => void>(() => {});

/** Fire a toast from any admin client component: `const toast = useAdminToast(); toast({ title: "Saved" })`. */
export const useAdminToast = () => useContext(Ctx);

/** Fire a toast from non-React code (or a component outside the provider). */
export function adminToast(title: string, opts?: { body?: string; tone?: ToastTone }) {
  if (typeof window === "undefined") return;
  window.dispatchEvent(new CustomEvent("adm:toast", { detail: { title, ...opts } }));
}

/**
 * Admin toast stack (bottom-right, polite live region). Auto-dismisses after
 * 5s (errors 9s); hovering pauses nothing on purpose — every toast here is a
 * receipt, never the only place an error is reported.
 */
export function Toaster({ children }: { children: React.ReactNode }) {
  const [toasts, setToasts] = useState<Toast[]>([]);
  const seq = useRef(0);

  const push = useCallback((t: { title: string; body?: string; tone?: ToastTone }) => {
    const id = ++seq.current;
    const tone = t.tone ?? "info";
    setToasts((xs) => [...xs.slice(-3), { id, title: t.title, body: t.body, tone }]);
    setTimeout(() => setToasts((xs) => xs.filter((x) => x.id !== id)), tone === "error" ? 9000 : 5000);
  }, []);

  useEffect(() => {
    const on = (e: Event) => {
      const d = (e as CustomEvent).detail ?? {};
      if (typeof d.title === "string") push({ title: d.title, body: d.body, tone: d.tone });
    };
    window.addEventListener("adm:toast", on);
    return () => window.removeEventListener("adm:toast", on);
  }, [push]);

  return (
    <Ctx.Provider value={push}>
      {children}
      <div className="adm-toasts" role="status" aria-live="polite">
        {toasts.map((t) => (
          <div key={t.id} className="adm-toast" data-tone={t.tone}>
            <span
              style={{ color: t.tone === "error" ? "var(--adm-red)" : t.tone === "success" ? "var(--adm-green)" : "var(--adm-cyan)", display: "inline-flex" }}
            >
              <AdmIcon name={t.tone === "error" ? "alert" : t.tone === "success" ? "check" : "bell"} size={16} />
            </span>
            <span className="min-w-0 flex-1">
              <span className="block font-semibold">{t.title}</span>
              {t.body && <span className="mt-0.5 block text-[12px]" style={{ color: "var(--adm-muted)" }}>{t.body}</span>}
            </span>
            <button
              type="button"
              className="adm-iconbtn"
              style={{ width: 24, height: 24 }}
              aria-label="Dismiss"
              onClick={() => setToasts((xs) => xs.filter((x) => x.id !== t.id))}
            >
              <AdmIcon name="close" size={13} />
            </button>
          </div>
        ))}
      </div>
    </Ctx.Provider>
  );
}

