"use client";

import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useCallback, useEffect, useLayoutEffect, useMemo, useState, useTransition } from "react";
import { breadcrumbsForPath } from "@/lib/admin-nav";
import { logout } from "@/lib/actions";
import AdminIndicators from "@/components/admin/AdminIndicators";
import VisitTracker from "@/components/VisitTracker";
import { TerminalDockProvider } from "@/components/customer/terminal/TerminalDock";
import { ComposeProvider } from "@/components/customer/mail/ComposeProvider";
import { MatrixProvider } from "@/components/customer/claude-code/MatrixProvider";
import { Sidebar } from "./Sidebar";
import { CommandPalette, type PaletteAction } from "./CommandPalette";
import { AlertsTray } from "./AlertsTray";
import { Toaster, adminToast } from "./Toaster";
import { Avatar } from "./Brand";
import { AdmIcon } from "./icons";
import {
  ADM_UI_COOKIE,
  serializeUiCookie,
  type ShellAlert,
  type ShellNavGroup,
  type ShellNotification,
  type ShellRoute,
  type ShellUiState,
  type ShellUser,
} from "./types";

export const ADM_THEME_KEY = "nxeon.admin.theme";
export const ADM_DENSITY_KEY = "nxeon.admin.density";

/** Routes that fill the whole content area (mail client, kanban boards). */
const FULL_BLEED = new Set(["/admin/inbox", "/admin/board", "/admin/reddit"]);
/** Data-table-heavy routes that need more than the default max width. */
const EXTRA_WIDE = new Set(["/admin/servers"]);
const WIDE = new Set(["/admin/visitors", "/admin/users", "/admin/jobs", "/admin/provisioning", "/admin/invoices"]);

function writeUiCookie(s: ShellUiState) {
  try {
    document.cookie = `${ADM_UI_COOKIE}=${serializeUiCookie(s)}; path=/admin; max-age=31536000; samesite=lax`;
  } catch {}
}

/**
 * The admin ops portal shell (2026-10-01 redesign). Replaces
 * components/portal/Shell.tsx for /admin only — /staff still renders that one.
 *
 * Owns: the rail (Sidebar), top bar (breadcrumbs, ⌘K search, theme + density
 * toggles, alerts tray, account menu), command palette, toasts, and the
 * shell-level providers every admin page may rely on (terminal dock, mail
 * composer, Matrix — the same three the old shell mounted; see CLAUDE.md on
 * why a provider added to one shell must exist on the other).
 *
 * Styling lives in app/admin/admin-shell.css, scoped to `:root.adm-portal`
 * (added to <html> here and by the layout's inline script).
 */
export function AdminShell({
  nav,
  routes,
  user,
  alerts,
  notifications,
  initialUi,
  children,
}: {
  nav: ShellNavGroup[];
  routes: ShellRoute[];
  user: ShellUser;
  alerts: ShellAlert[];
  notifications: ShellNotification[];
  initialUi: ShellUiState;
  children: React.ReactNode;
}) {
  const pathname = usePathname() ?? "/admin";
  const router = useRouter();
  const [ui, setUi] = useState<ShellUiState>(initialUi);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [paletteOpen, setPaletteOpen] = useState(false);
  const [accountOpen, setAccountOpen] = useState(false);
  const [theme, setTheme] = useState<"dark" | "light">("dark");
  const [density, setDensity] = useState<"comfortable" | "compact">("comfortable");
  const [isDesktop, setIsDesktop] = useState(true);
  const [, startTransition] = useTransition();

  /* <html> scope class. The layout's inline script adds it before first paint;
     this keeps it correct across client-side enter/exit, and drops the
     customer portal's `data-theme` so none of its bare light-mode rules can
     apply here (restored on the way out). */
  useLayoutEffect(() => {
    const root = document.documentElement;
    root.classList.add("adm-portal");
    const prevTheme = root.getAttribute("data-theme");
    if (prevTheme) root.removeAttribute("data-theme");
    return () => {
      root.classList.remove("adm-portal");
      root.removeAttribute("data-adm-theme");
      root.removeAttribute("data-adm-density");
      if (prevTheme) root.setAttribute("data-theme", prevTheme);
    };
  }, []);

  // Hydrate theme/density from what the inline script already applied.
  useEffect(() => {
    const root = document.documentElement;
    setTheme(root.getAttribute("data-adm-theme") === "light" ? "light" : "dark");
    setDensity(root.getAttribute("data-adm-density") === "compact" ? "compact" : "comfortable");
  }, []);

  const applyTheme = useCallback((t: "dark" | "light") => {
    setTheme(t);
    document.documentElement.setAttribute("data-adm-theme", t);
    try { localStorage.setItem(ADM_THEME_KEY, t); } catch {}
  }, []);
  const applyDensity = useCallback((d: "comfortable" | "compact") => {
    setDensity(d);
    if (d === "compact") document.documentElement.setAttribute("data-adm-density", "compact");
    else document.documentElement.removeAttribute("data-adm-density");
    try { localStorage.setItem(ADM_DENSITY_KEY, d); } catch {}
  }, []);

  const updateUi = useCallback((fn: (s: ShellUiState) => ShellUiState) => {
    setUi((prev) => {
      const next = fn(prev);
      writeUiCookie(next);
      return next;
    });
  }, []);
  const toggleRail = useCallback(() => updateUi((s) => ({ ...s, railCollapsed: !s.railCollapsed })), [updateUi]);

  useEffect(() => {
    const mq = window.matchMedia("(min-width: 1024px)");
    const sync = () => setIsDesktop(mq.matches);
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);
  useEffect(() => {
    document.documentElement.style.setProperty("--nx-rail-w", ui.railCollapsed ? "4.25rem" : "16rem");
  }, [ui.railCollapsed]);

  useEffect(() => {
    setDrawerOpen(false);
    setAccountOpen(false);
  }, [pathname]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement | null;
      const typing = !!t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName));
      if (e.key === "Escape") {
        setDrawerOpen(false);
        setAccountOpen(false);
      }
      if (!typing && e.key === "[" && !e.metaKey && !e.ctrlKey && !e.altKey) toggleRail();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [toggleRail]);

  const actions: PaletteAction[] = useMemo(() => {
    const has = (href: string) => routes.some((r) => r.href === href);
    const list: PaletteAction[] = [];
    if (has("/admin/grant")) list.push({ key: "grant", label: "Grant a free VPS", icon: "server", run: () => router.push("/admin/grant"), keywords: "comp" });
    if (has("/admin/coupons")) list.push({ key: "coupon", label: "Create a coupon", icon: "gift", run: () => router.push("/admin/coupons"), keywords: "discount promo" });
    if (has("/admin/support")) list.push({ key: "tickets", label: "Open tickets awaiting reply", icon: "ticket", run: () => router.push("/admin/support") });
    if (has("/admin/jobs")) list.push({ key: "failed", label: "Review failed jobs", icon: "alert", run: () => router.push("/admin/jobs"), keywords: "errors queue" });
    if (has("/admin/announcements")) list.push({ key: "announce", label: "Post a What's New announcement", icon: "megaphone", run: () => router.push("/admin/announcements") });
    list.push(
      { key: "theme", label: theme === "dark" ? "Switch to light theme" : "Switch to dark theme", icon: theme === "dark" ? "sun" : "moon", run: () => applyTheme(theme === "dark" ? "light" : "dark"), keywords: "appearance mode" },
      { key: "density", label: density === "compact" ? "Comfortable density" : "Compact density", icon: "density", run: () => applyDensity(density === "compact" ? "comfortable" : "compact"), keywords: "rows spacing" },
      { key: "rail", label: ui.railCollapsed ? "Expand sidebar" : "Collapse sidebar", sub: "Shortcut: [", icon: "collapse", run: toggleRail },
      { key: "copy", label: "Copy link to this page", icon: "external", run: () => { navigator.clipboard?.writeText(window.location.href).then(() => adminToast("Link copied", { tone: "success" })).catch(() => {}); } },
    );
    return list;
  }, [routes, router, theme, density, ui.railCollapsed, applyTheme, applyDensity, toggleRail]);

  const crumbs = breadcrumbsForPath(pathname);
  const fullBleed = FULL_BLEED.has(pathname);
  const maxW = EXTRA_WIDE.has(pathname) ? "120rem" : WIDE.has(pathname) ? "100rem" : "88rem";

  return (
    <TerminalDockProvider>
      <ComposeProvider>
        <MatrixProvider>
          <Toaster>
            <div className="adm-shell-root">
              <VisitTracker kind="portal" />
              <AdminIndicators isStaffPortal={false} showSupport showInbox />
              <CommandPalette routes={routes} actions={actions} open={paletteOpen} onOpenChange={setPaletteOpen} />

              <Sidebar
                groups={nav}
                pathname={pathname}
                ui={ui}
                isDesktop={isDesktop}
                open={drawerOpen}
                onClose={() => setDrawerOpen(false)}
                onToggleRail={toggleRail}
                onToggleGroup={(k) =>
                  updateUi((s) => ({
                    ...s,
                    collapsedGroups: s.collapsedGroups.includes(k) ? s.collapsedGroups.filter((x) => x !== k) : [...s.collapsedGroups, k],
                  }))
                }
                onToggleMore={(k) =>
                  updateUi((s) => ({
                    ...s,
                    openMore: s.openMore.includes(k) ? s.openMore.filter((x) => x !== k) : [...s.openMore, k],
                  }))
                }
              />
              {drawerOpen && !isDesktop && <div className="adm-scrim" onClick={() => setDrawerOpen(false)} aria-hidden />}

              <div className="flex min-w-0 flex-1 flex-col">
                <header className="adm-topbar">
                  <button
                    type="button"
                    className="adm-iconbtn lg:hidden"
                    aria-label="Open menu"
                    aria-expanded={drawerOpen}
                    aria-controls="adm-rail"
                    onClick={() => setDrawerOpen(true)}
                  >
                    <AdmIcon name="menu" />
                  </button>
                  <nav aria-label="Breadcrumb" className="adm-crumbs hidden min-w-0 md:flex" style={{ margin: 0 }}>
                    {crumbs.map((c, i) => (
                      <span key={i} className="flex items-center gap-1.5">
                        {i > 0 && <AdmIcon name="chevronRight" size={12} />}
                        {c.href && i < crumbs.length - 1 ? (
                          <Link href={c.href}>{c.label}</Link>
                        ) : (
                          <span aria-current={i === crumbs.length - 1 ? "page" : undefined}>{c.label}</span>
                        )}
                      </span>
                    ))}
                  </nav>
                  <button type="button" className="adm-search md:ml-auto" onClick={() => setPaletteOpen(true)} aria-label="Search and commands (Ctrl+K)">
                    <AdmIcon name="search" size={15} />
                    <span className="truncate">Search clients, servers, IPs…</span>
                    <span className="kbd ml-auto hidden sm:inline">⌘K</span>
                  </button>
                  <div className="ml-auto flex items-center gap-1 md:ml-2">
                    <button
                      type="button"
                      className="adm-iconbtn hidden sm:inline-flex"
                      aria-label={density === "compact" ? "Switch to comfortable density" : "Switch to compact density"}
                      aria-pressed={density === "compact"}
                      title={density === "compact" ? "Compact density" : "Comfortable density"}
                      onClick={() => applyDensity(density === "compact" ? "comfortable" : "compact")}
                    >
                      <AdmIcon name={density === "compact" ? "density" : "comfy"} />
                    </button>
                    <button
                      type="button"
                      className="adm-iconbtn"
                      aria-label={theme === "dark" ? "Switch to light theme" : "Switch to dark theme"}
                      title={theme === "dark" ? "Light theme" : "Dark theme"}
                      onClick={() => applyTheme(theme === "dark" ? "light" : "dark")}
                    >
                      <AdmIcon name={theme === "dark" ? "sun" : "moon"} />
                    </button>
                    <AlertsTray initialAlerts={alerts} initialNotifications={notifications} />
                    <div className="relative">
                      <button
                        type="button"
                        className="flex items-center gap-2 rounded-xl py-1 pl-1 pr-2 transition-colors hover:bg-[var(--adm-hover)]"
                        aria-haspopup="menu"
                        aria-expanded={accountOpen}
                        onClick={() => setAccountOpen((v) => !v)}
                      >
                        <Avatar name={user.name} email={user.email} src={user.avatarUrl} size={30} />
                        <span className="hidden text-left leading-tight xl:block">
                          <span className="block text-[12.5px] font-semibold" style={{ color: "var(--adm-ink)" }}>{user.name}</span>
                          <span className="block text-[11px]" style={{ color: "var(--adm-faint)" }}>{user.role.toLowerCase()}</span>
                        </span>
                      </button>
                      {accountOpen && (
                        <div className="adm-pop" role="menu" style={{ width: "16rem" }}>
                          <div className="flex items-center gap-3 px-4 py-3" style={{ borderBottom: "1px solid var(--adm-line)" }}>
                            <Avatar name={user.name} email={user.email} src={user.avatarUrl} size={36} />
                            <div className="min-w-0">
                              <p className="truncate text-[13px] font-semibold" style={{ color: "var(--adm-ink)" }}>{user.name}</p>
                              <p className="truncate text-[11.5px]" style={{ color: "var(--adm-muted)" }}>{user.email}</p>
                            </div>
                          </div>
                          <Link role="menuitem" href="/dashboard/settings" className="adm-pop-row" style={{ borderBottom: 0 }}>
                            <AdmIcon name="shield" size={16} /> Security &amp; 2FA
                          </Link>
                          <button
                            role="menuitem"
                            type="button"
                            className="adm-pop-row w-full text-left"
                            style={{ borderBottom: 0 }}
                            onClick={() => startTransition(() => logout())}
                          >
                            <AdmIcon name="logout" size={16} /> Sign out
                          </button>
                        </div>
                      )}
                    </div>
                  </div>
                </header>

                {fullBleed ? (
                  <main id="adm-main" className="min-h-0 flex-1 overflow-hidden">{children}</main>
                ) : (
                  <main id="adm-main" className="adm-main" style={{ maxWidth: maxW }}>
                    {children}
                  </main>
                )}
              </div>
            </div>
          </Toaster>
        </MatrixProvider>
      </ComposeProvider>
    </TerminalDockProvider>
  );
}

