                    <button
                      type="button"
                      className="adm-iconbtn hidden sm:inline-flex"
                      aria-label={density === "compact" ? "Switch to comfortable density" : "Switch to compact density"}
                      aria-pressed={density === "compact"}
                      title={density === "compact" ? "Compact density" : "Comfortable density"}
                      onClick={() => applyDensity(density === "compact" ? "comfortable" : "compact")}
                    >
                      <AdmIcon name={density === "compact" ? "density" : "comfy"} />
                    </button>
                    <button
