        {eyebrow && <p className="adm-eyebrow mb-1.5">{eyebrow}</p>}
        <h1 className="page-title">{title}</h1>
        {sub && <p className="mt-1 text-sm" style={{ color: "var(--adm-muted)" }}>{sub}</p>}
      </div>
      {children && <div className="flex flex-wrap items-center gap-2">{children}</div>}
    </div>
  );
}

export function Panel({
  title,
  action,
  children,
  className = "",
  bodyClassName = "",
  id,
}: {
  title?: React.ReactNode;
  action?: { href: string; label: string } | React.ReactNode;
  children: React.ReactNode;
  className?: string;
  bodyClassName?: string;
  id?: string;
}) {
  const act =
    action && typeof action === "object" && "href" in (action as object) ? (
      <Link href={(action as { href: string }).href} className="adm-panel-link">
        {(action as { label: string }).label} →
      </Link>
    ) : (
      (action as React.ReactNode)
    );
  return (
    <section className={`adm-panel ${className}`} aria-labelledby={id}>
      {title && (
        <div className="adm-panel-head">
          <h2 id={id} className="adm-panel-title">{title}</h2>
          {act}
        </div>
      )}
      <div className={bodyClassName}>{children}</div>
    </section>
  );
}

export type DeltaDir = "up" | "down" | "flat";

/** Today-vs-yesterday style comparison. `goodWhen` flips colour semantics for "less is better" metrics. */
export function Delta({ now, prev, goodWhen = "up", suffix = "vs yesterday", format }: {
  now: number;
  prev: number;
  goodWhen?: "up" | "down";
  suffix?: string;
  format?: (n: number) => string;
}) {
  const diff = now - prev;
  const dir: DeltaDir = diff === 0 ? "flat" : diff > 0 ? "up" : "down";
  const good = dir === "flat" ? "flat" : (dir === goodWhen ? "up" : "down");
  const fmt = format ?? ((n: number) => String(n));
  return (
    <span className="adm-delta" data-dir={good}>
      {dir === "up" ? "▲" : dir === "down" ? "▼" : "•"} {dir === "flat" ? "same" : fmt(Math.abs(diff))}
      <span style={{ color: "var(--adm-faint)", fontWeight: 500 }}>&nbsp;{suffix}</span>
    </span>
  );
}

export function Kpi({
  label,
  value,
  sub,
  href,
  tone,
  children,
}: {
  label: string;
  value: React.ReactNode;
  sub?: React.ReactNode;
  href?: string;
  tone?: "alert" | "warn";
  children?: React.ReactNode;
}) {
  const inner = (
    <>
      <span className="adm-kpi-label">{label}</span>
      <span className="adm-kpi-value">{value}</span>
      {sub && <span className="adm-kpi-sub">{sub}</span>}
      {children}
    </>
  );
  return href ? (
    <Link href={href} className="adm-kpi" data-tone={tone}>{inner}</Link>
  ) : (
    <div className="adm-kpi" data-tone={tone}>{inner}</div>
  );
}

export function Pill({ tone, children }: { tone?: "green" | "red" | "amber" | "blue"; children: React.ReactNode }) {
  return <span className="adm-pill" data-tone={tone}>{children}</span>;
}

export function Meter({ pct, warnAt = 80, alertAt = 90, label }: { pct: number; warnAt?: number; alertAt?: number; label?: string }) {
  const p = Math.max(0, Math.min(100, pct));
  return (
    <div
      className="adm-meter"
      data-tone={p >= alertAt ? "alert" : p >= warnAt ? "warn" : undefined}
      role="meter"
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(p)}
      aria-label={label}
    >
      <span style={{ width: `${p}%` }} />
    </div>
  );
}

export function EmptyRow({ children }: { children: React.ReactNode }) {
  return <p className="px-5 py-8 text-center text-[13px]" style={{ color: "var(--adm-muted)" }}>{children}</p>;
}

/** Loading placeholder for a streamed panel. */
export function PanelSkeleton({ rows = 4, title }: { rows?: number; title?: string }) {
  return (
    <section className="adm-panel" aria-busy="true">
      <div className="adm-panel-head">
        <span className="adm-panel-title">{title ?? <span className="skeleton inline-block h-4 w-32" />}</span>
      </div>
      <div className="space-y-3 p-5">
        {Array.from({ length: rows }).map((_, i) => (
          <div key={i} className="skeleton h-4" style={{ width: `${88 - i * 12}%` }} />
        ))}
      </div>
    </section>
  );
}

/** Inline error for a panel whose data source failed — says what, never a stack trace. */
export function PanelError({ children }: { children: React.ReactNode }) {
  return (
    <p className="flex items-center gap-2 px-5 py-6 text-[13px]" style={{ color: "var(--adm-amber)" }}>
      <span aria-hidden>⚠</span> {children}
    </p>
  );
}

