import "server-only";
import { db } from "@/lib/db";
import {
  REVENUE_WHERE,
  REVENUE_USER_WHERE,
  fleetMrrCents,
  currentRenewalPrices,
} from "@/lib/admin-metrics";

/**
 * Data for the admin command center (app/admin/page.tsx). READ-ONLY, real
 * rows only: every number is a count or a sum over the database — nothing is
 * estimated, extrapolated or smoothed. "Today" is the current UTC calendar
 * day and "yesterday" the one before it (the page labels it UTC), so the two
 * are like-for-like whole days only once today has ended; the page shows
 * today-so-far against all of yesterday and says so.
 */

export function utcDayBounds(now = new Date()) {
  const todayStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
  const yesterdayStart = new Date(todayStart.getTime() - 86_400_000);
  return { todayStart, yesterdayStart, now };
}

const soft = <T,>(p: Promise<T>, fb: T): Promise<T> => p.catch(() => fb);

export async function loadPulse() {
  const { todayStart, yesterdayStart, now } = utcDayBounds();
  const since24h = new Date(now.getTime() - 24 * 3600_000);
  const since48h = new Date(now.getTime() - 48 * 3600_000);
  const revIn = (gte: Date, lt: Date) =>
    soft(db.walletTransaction.aggregate({ _sum: { amountCents: true }, where: { ...REVENUE_WHERE, createdAt: { gte, lt } } }), {
      _sum: { amountCents: 0 },
    } as { _sum: { amountCents: number | null } });

  const [
    revToday, revYesterday,
    signupsToday, signupsYesterday,
    ordersToday, ordersYesterday,
    ticketsAwaiting, oldestAwaiting, ticketsOpenedToday,
    failed24, failedPrev24,
    queued, running, oldestQueued,
    activeServers, renewalPrices, runningServers, totalServers,
    liabilities,
  ] = await Promise.all([
    revIn(todayStart, now),
    revIn(yesterdayStart, todayStart),
    soft(db.user.count({ where: { role: "CUSTOMER", createdAt: { gte: todayStart } } }), 0),
    soft(db.user.count({ where: { role: "CUSTOMER", createdAt: { gte: yesterdayStart, lt: todayStart } } }), 0),
    soft(db.server.count({ where: { isFree: false, createdAt: { gte: todayStart }, user: REVENUE_USER_WHERE } }), 0),
    soft(db.server.count({ where: { isFree: false, createdAt: { gte: yesterdayStart, lt: todayStart }, user: REVENUE_USER_WHERE } }), 0),
    soft(db.ticket.count({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } } }), 0),
    soft(db.ticket.findFirst({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } }, orderBy: { updatedAt: "asc" }, select: { updatedAt: true } }), null),
    soft(db.ticket.count({ where: { createdAt: { gte: todayStart } } }), 0),
    soft(db.job.count({ where: { status: "FAILED", updatedAt: { gte: since24h } } }), 0),
    soft(db.job.count({ where: { status: "FAILED", updatedAt: { gte: since48h, lt: since24h } } }), 0),
    soft(db.job.count({ where: { status: "QUEUED" } }), 0),
    soft(db.job.count({ where: { status: "RUNNING" } }), 0),
    soft(db.job.findFirst({ where: { status: "QUEUED" }, orderBy: { createdAt: "asc" }, select: { createdAt: true } }), null),
    soft(
      db.server.findMany({
        where: { isFree: false, status: { notIn: ["DELETING"] }, user: { excludeFromRevenue: false } },
        select: {
          status: true, isFree: true, termMonths: true, extraDiskGB: true, backupTier: true, annualDiscountPct: true,
          plan: { select: { name: true, priceCents: true } },
          gamePlan: { select: { name: true, priceCents: true, termMonths: true } },
          dedicatedIp: { select: { id: true } },
          wantsDedicatedIp: true,
          grandfatheredRenewalCents: true,
        },
      }),
      [],
    ),
    currentRenewalPrices(),
    soft(db.server.count({ where: { status: "RUNNING" } }), 0),
    soft(db.server.count({ where: { status: { notIn: ["DELETING"] } } }), 0),
    soft(db.user.aggregate({ _sum: { balanceCents: true }, where: REVENUE_USER_WHERE }), { _sum: { balanceCents: 0 } } as { _sum: { balanceCents: number | null } }),
  ]);

  return {
    revenueToday: -(revToday._sum.amountCents ?? 0),
    revenueYesterday: -(revYesterday._sum.amountCents ?? 0),
    signupsToday, signupsYesterday,
    ordersToday, ordersYesterday,
    ticketsAwaiting, oldestAwaitingAt: oldestAwaiting?.updatedAt ?? null, ticketsOpenedToday,
    failed24, failedPrev24,
    queued, running, oldestQueuedAt: oldestQueued?.createdAt ?? null,
    mrrCents: fleetMrrCents(activeServers, renewalPrices),
    billableServers: activeServers.filter((s) => s.status !== "SUSPENDED").length,
    runningServers, totalServers,
    liabilitiesCents: liabilities._sum.balanceCents ?? 0,
  };
}

export async function loadQueueAndDeploys() {
  const [inFlight, deploys, failures, statusCounts] = await Promise.all([
    soft(
      db.job.findMany({
        where: { status: { in: ["QUEUED", "RUNNING"] } },
        select: { id: true, type: true, status: true, progress: true, step: true, createdAt: true, server: { select: { id: true, hostname: true } } },
        orderBy: { createdAt: "asc" },
        take: 8,
      }),
      [],
    ),
    // "Recent deploys" = customer provisions, newest first, whatever their outcome.
    soft(
      db.job.findMany({
        where: { type: "PROVISION" },
        select: {
          id: true, status: true, createdAt: true, updatedAt: true, error: true,
          server: { select: { id: true, hostname: true, label: true, gameVariant: true, user: { select: { email: true } }, node: { select: { name: true } } } },
        },
        orderBy: { createdAt: "desc" },
        take: 7,
      }),
      [],
    ),
    soft(
      db.job.findMany({
        where: { status: "FAILED" },
        select: { id: true, type: true, error: true, updatedAt: true, server: { select: { id: true, hostname: true } } },
        orderBy: { updatedAt: "desc" },
        take: 5,
      }),
      [],
    ),
    soft(db.server.groupBy({ by: ["status"], _count: { _all: true } }), [] as { status: string; _count: { _all: number } }[]),
  ]);
  return { inFlight, deploys, failures, statusCounts };
}

export async function loadOpenNodeAlerts() {
  return soft(
    db.nodeAlert.findMany({
      where: { status: "OPEN" },
      select: { id: true, nodeName: true, dimension: true, severity: true, pct: true, detail: true, updatedAt: true },
      orderBy: [{ severity: "asc" }, { updatedAt: "desc" }],
      take: 6,
    }),
    [],
  );
}

