"use client";

import { useEffect, useState } from "react";
import { AreaChart } from "@/components/ui/charts";

// Deliberately NOT importing these from lib/admin-metrics: that module pulls
// in `db` (Prisma) and is server-only. This is a "use client" component, so
// the range keys/labels are duplicated here — keep in sync with
// `REVENUE_RANGES` in lib/admin-metrics.ts if a range is ever added/renamed.
export type RevenueRange = "today" | "7d" | "14d" | "1m" | "all";
const REVENUE_RANGES: { key: RevenueRange; label: string }[] = [
  { key: "today", label: "Today" },
  { key: "7d", label: "7 days" },
  { key: "14d", label: "14 days" },
  { key: "1m", label: "1 month" },
  { key: "all", label: "All time" },
];

/**
 * Client-side time-range toggle for the Operations Overview "Revenue" card.
 * Renders instantly with the server-rendered default range (`initialRange`,
 * fetched by app/admin/page.tsx via `revenueSeriesForRange` — no extra
 * request on first paint) and re-fetches `/api/admin/revenue-chart` — a real,
 * range-scoped DB aggregation, not a client-side slice of the initial
 * dataset — whenever a different range is picked.
 */
export function RevenueRangeChart({
  initialRange,
  initialSeries,
  initialXLabels,
  initialTotal,
}: {
  initialRange: RevenueRange;
  initialSeries: number[];
  initialXLabels: string[];
  initialTotal: number;
}) {
