import Link from "next/link";
import { Suspense } from "react";
import { requireArea } from "@/lib/rbac";
import { canAccess } from "@/lib/rbac";
import { db } from "@/lib/db";
import { fmtMoney, timeAgo, StatusDot } from "@/components/ui/primitives";
import { AutoRefresh } from "@/components/AutoRefresh";
import { RevenueRangeChart } from "@/components/admin/RevenueRangeChart";
import { actingAdminId, revenueSeriesForRange } from "@/lib/admin-metrics";
import { allNodeUtil } from "@/lib/node-capacity";
import { loadPulse, loadQueueAndDeploys, loadOpenNodeAlerts } from "@/lib/admin/command-center";
import {
  AdmPageHeader,
  Delta,
  EmptyRow,
  Kpi,
  Meter,
  Panel,
  PanelError,
  PanelSkeleton,
  Pill,
} from "@/components/admin/shell/primitives";

export const dynamic = "force-dynamic";

const fmtAge = (d: Date | null) => (d ? timeAgo(d).replace(" ago", "") : "—");
const jobLabel = (t: string) => t.toLowerCase().replace(/_/g, " ");

/**
 * COMMAND CENTER — the admin home (2026-10-01 redesign).
 *
 * Top: today's pulse (revenue, signups, orders, tickets, failed jobs, queue)
 * against yesterday, every figure a real DB count/sum (lib/admin/command-center.ts).
 * Middle: what needs a human now (alerts, failures, in-flight jobs) and the
 * fleet's capacity. Bottom: revenue trend, recent deploys, activity.
 *
 * Slow sources (live Proxmox reads for capacity) stream in behind Suspense so
 * an unreachable node never holds the whole page hostage.
 */
export default async function AdminCommandCenter() {
  const user = await requireArea("overview");
  const fleet = canAccess(user.role, "fleet");
  const billing = canAccess(user.role, "billing");
  const support = canAccess(user.role, "supportTickets");
  const audit = canAccess(user.role, "platform");

  const [pulse, queue, nodeAlerts, revenue14d] = await Promise.all([
    loadPulse(),
    fleet ? loadQueueAndDeploys() : Promise.resolve(null),
    fleet ? loadOpenNodeAlerts() : Promise.resolve([]),
    billing ? revenueSeriesForRange("14d") : Promise.resolve(null),
  ]);

  const queueBusy = pulse.queued + pulse.running > 0;
  const stamp = new Date().toISOString().slice(11, 16);

  return (
    <div className="space-y-5">
      {queueBusy && <AutoRefresh intervalMs={15000} />}
      <AdmPageHeader
        eyebrow="Command center"
        title={`Good ${greeting()}, ${user.name.split(" ")[0] || "there"}`}
        sub={
          <>
            Live state of the platform · today is the current UTC day, compared with all of yesterday · as of {stamp} UTC
          </>
        }
      >
        {fleet && <Link href="/admin/monitoring" className="btn-secondary">Monitoring</Link>}
        {fleet && <Link href="/admin/grant" className="btn-primary">Grant VPS</Link>}
      </AdmPageHeader>

      {/* ── Pulse ─────────────────────────────────────────────────────── */}
      <div className="grid grid-cols-2 gap-3 md:grid-cols-3 xl:grid-cols-6">
        {billing && (
          <Kpi label="Revenue today" value={fmtMoney(pulse.revenueToday)} href="/admin/billing"
            sub={<Delta now={pulse.revenueToday} prev={pulse.revenueYesterday} format={(n) => fmtMoney(n)} />} />
        )}
        <Kpi label="New signups today" value={pulse.signupsToday} href="/admin/users"
          sub={<Delta now={pulse.signupsToday} prev={pulse.signupsYesterday} />} />
        {fleet && (
          <Kpi label="Paid orders today" value={pulse.ordersToday} href="/admin/servers"
            sub={<Delta now={pulse.ordersToday} prev={pulse.ordersYesterday} />} />
        )}
        {support && (
          <Kpi label="Tickets awaiting reply" value={pulse.ticketsAwaiting} href="/admin/support"
            tone={pulse.ticketsAwaiting > 0 ? "warn" : undefined}
            sub={pulse.ticketsAwaiting > 0 ? `oldest waiting ${fmtAge(pulse.oldestAwaitingAt)} · ${pulse.ticketsOpenedToday} opened today` : `queue clear · ${pulse.ticketsOpenedToday} opened today`} />
        )}
        {fleet && (
          <Kpi label="Failed jobs · 24h" value={pulse.failed24} href="/admin/jobs"
            tone={pulse.failed24 > 0 ? "alert" : undefined}
            sub={<Delta now={pulse.failed24} prev={pulse.failedPrev24} goodWhen="down" suffix="vs previous 24h" />} />
        )}
        {fleet && (
          <Kpi label="Job queue" value={`${pulse.running} running`} href="/admin/provisioning"
            tone={pulse.oldestQueuedAt && Date.now() - pulse.oldestQueuedAt.getTime() > 10 * 60_000 ? "warn" : undefined}
            sub={pulse.queued > 0 ? `${pulse.queued} queued · oldest ${fmtAge(pulse.oldestQueuedAt)}` : "nothing queued"} />
        )}
      </div>

      <div className="grid grid-cols-2 gap-3 md:grid-cols-4">
        {billing && (
          <Kpi label="MRR (committed)" value={fmtMoney(pulse.mrrCents)} href="/admin/subscriptions"
            sub={`${pulse.billableServers} billable servers`} />
        )}
        {fleet && (
          <Kpi label="Servers" value={pulse.totalServers} href="/admin/servers"
            sub={`${pulse.runningServers} running`} />
        )}
        {billing && (
          <Kpi label="Wallet liabilities" value={fmtMoney(pulse.liabilitiesCents)} href="/admin/billing"
            sub="customer balances held" />
        )}
        {fleet && (
          <Kpi label="Node alerts open" value={nodeAlerts.length} href="/admin/nodes"
            tone={nodeAlerts.some((a) => a.severity === "CRITICAL") ? "alert" : nodeAlerts.length ? "warn" : undefined}
            sub={nodeAlerts.length ? nodeAlerts.map((a) => `${a.nodeName} ${a.dimension.toLowerCase()}`).slice(0, 2).join(" · ") : "all nodes within thresholds"} />
        )}
      </div>

      {/* ── Needs attention + capacity ────────────────────────────────── */}
      {fleet && queue && (
        <div className="grid gap-4 xl:grid-cols-5">
          <Panel title="Needs attention" action={{ href: "/admin/jobs", label: "All jobs" }} className="xl:col-span-3">
            {queue.failures.length === 0 && nodeAlerts.length === 0 && queue.inFlight.length === 0 ? (
              <EmptyRow>Nothing is failing or in flight. </EmptyRow>
            ) : (
              <ul className="adm-list">
                {nodeAlerts.map((a) => (
                  <li key={a.id} className="flex items-start gap-3 px-5 py-3 text-[13px]">
                    <Pill tone={a.severity === "CRITICAL" ? "red" : "amber"}>{a.severity.toLowerCase()}</Pill>
                    <div className="min-w-0 flex-1">
                      <Link href="/admin/nodes" className="font-semibold hover:underline" style={{ color: "var(--adm-ink)" }}>
                        {a.nodeName} · {a.dimension} {a.pct}%
                      </Link>
                      <p className="truncate text-[12px]" style={{ color: "var(--adm-muted)" }}>{a.detail}</p>
                    </div>
                    <span className="shrink-0 text-[11.5px]" style={{ color: "var(--adm-faint)" }}>{timeAgo(a.updatedAt)}</span>
                  </li>
                ))}
                {queue.failures.map((j) => (
                  <li key={j.id} className="flex items-start gap-3 px-5 py-3 text-[13px]">
                    <Pill tone="red">failed</Pill>
                    <div className="min-w-0 flex-1">
                      {j.server ? (
                        <Link href={`/admin/servers/${j.server.id}`} className="font-semibold hover:underline" style={{ color: "var(--adm-ink)" }}>
                          {jobLabel(j.type)} · {j.server.hostname}
                        </Link>
                      ) : (
                        <span className="font-semibold" style={{ color: "var(--adm-ink)" }}>{jobLabel(j.type)}</span>
                      )}
                      {j.error && <p className="truncate font-mono text-[11.5px]" style={{ color: "var(--adm-muted)" }}>{j.error}</p>}
                    </div>
                    <span className="shrink-0 text-[11.5px]" style={{ color: "var(--adm-faint)" }}>{timeAgo(j.updatedAt)}</span>
                  </li>
                ))}
                {queue.inFlight.map((j) => (
                  <li key={j.id} className="flex items-center gap-3 px-5 py-3 text-[13px]">
                    <Pill tone={j.status === "RUNNING" ? "blue" : undefined}>{j.status.toLowerCase()}</Pill>
                    <div className="min-w-0 flex-1">
                      {j.server ? (
                        <Link href={`/admin/servers/${j.server.id}`} className="font-medium hover:underline" style={{ color: "var(--adm-ink)" }}>
                          {jobLabel(j.type)} · {j.server.hostname}
                        </Link>
                      ) : (
                        <span>{jobLabel(j.type)}</span>
                      )}
                      {j.status === "RUNNING" && (
                        <div className="mt-1.5 flex items-center gap-2">
                          <div className="w-40"><Meter pct={j.progress} warnAt={101} alertAt={101} label="progress" /></div>
                          <span className="text-[11.5px]" style={{ color: "var(--adm-faint)" }}>{j.step ?? `${j.progress}%`}</span>
                        </div>
                      )}
                    </div>
                    <span className="shrink-0 text-[11.5px]" style={{ color: "var(--adm-faint)" }}>{timeAgo(j.createdAt)}</span>
                  </li>
                ))}
              </ul>
            )}
          </Panel>

          <div className="xl:col-span-2">
            <Suspense fallback={<PanelSkeleton title="Node capacity" rows={5} />}>
              <CapacityPanel />
            </Suspense>
          </div>
        </div>
      )}

      {/* ── Trend + deploys + activity ────────────────────────────────── */}
      <div className="grid gap-4 xl:grid-cols-3">
        {billing && revenue14d && (
          <RevenueRangeChart
            initialRange="14d"
            initialSeries={revenue14d.series}
            initialXLabels={revenue14d.xLabels}
            initialTotal={revenue14d.total}
          />
        )}
        {fleet && queue && (
          <Panel title="Recent deploys" action={{ href: "/admin/provisioning", label: "Provisioning" }}>
            {queue.deploys.length === 0 ? (
              <EmptyRow>No provisions yet.</EmptyRow>
            ) : (
              <ul className="adm-list">
                {queue.deploys.map((d) => (
                  <li key={d.id} className="flex items-center gap-3 px-5 py-2.5 text-[13px]">
                    <StatusDot status={d.status} label={d.status === "DONE" ? "live" : undefined} />
                    <div className="min-w-0 flex-1">
                      {d.server ? (
                        <Link href={`/admin/servers/${d.server.id}`} className="block truncate font-medium hover:underline" style={{ color: "var(--adm-ink)" }}>
                          {d.server.label || d.server.hostname}
                        </Link>
                      ) : (
                        <span className="block truncate">deleted server</span>
                      )}
                      <span className="block truncate text-[11.5px]" style={{ color: "var(--adm-faint)" }}>
                        {[d.server?.gameVariant ? "game" : "vps", d.server?.node?.name, d.server?.user.email].filter(Boolean).join(" · ")}
                      </span>
                    </div>
                    <span className="shrink-0 text-[11.5px]" style={{ color: "var(--adm-faint)" }}>{timeAgo(d.createdAt)}</span>
                  </li>
                ))}
              </ul>
            )}
          </Panel>
        )}
        {audit && (
          <Suspense fallback={<PanelSkeleton title="Activity" rows={6} />}>
            <ActivityPanel />
          </Suspense>
        )}
      </div>

      {fleet && queue && queue.statusCounts.length > 0 && (
        <Panel title="Fleet by status" action={{ href: "/admin/servers", label: "Servers" }}>
          <div className="flex flex-wrap gap-2 p-4">
            {queue.statusCounts
              .sort((a, b) => b._count._all - a._count._all)
              .map((s) => (
                <Link key={s.status} href={`/admin/servers?status=${s.status}`} className="adm-pill hover:border-[var(--adm-line-3)]">
                  <StatusDot status={s.status} /> <span style={{ color: "var(--adm-ink)" }}>{s._count._all}</span>
                </Link>
              ))}
          </div>
        </Panel>
      )}
    </div>
  );
}

function greeting() {
  const h = new Date().getUTCHours();
  return h < 12 ? "morning" : h < 18 ? "afternoon" : "evening";
}

/** Streams in: allNodeUtil() makes live Proxmox reads that can be slow. */
async function CapacityPanel() {
  let data: Awaited<ReturnType<typeof allNodeUtil>> | null = null;
  try {
    data = await Promise.race([
      allNodeUtil(),
      new Promise<null>((r) => setTimeout(() => r(null), 8000)),
    ]);
  } catch {
    data = null;
  }
  return (
    <Panel title="Node capacity" action={{ href: "/admin/nodes", label: "Nodes" }} className="h-full">
      {!data ? (
        <PanelError>Capacity readings didn&apos;t arrive within 8s — node APIs may be unreachable. Full detail on Monitoring.</PanelError>
      ) : data.nodes.filter((n) => n.enabled).length === 0 ? (
        <EmptyRow>No enabled nodes.</EmptyRow>
      ) : (
        <ul className="adm-list">
          {data.nodes
            .filter((n) => n.enabled)
            .map((n) => (
              <li key={`${n.kind}:${n.id}`} className="px-5 py-3">
                <div className="mb-2 flex items-center gap-2 text-[13px]">
                  <span className="font-semibold" style={{ color: "var(--adm-ink)" }}>{n.name}</span>
                  <span className="text-[11px]" style={{ color: "var(--adm-faint)" }}>{n.kind === "HOSTING" ? "web hosting" : "proxmox"}</span>
                  <span className="ml-auto">
                    {!n.reachable ? (
                      <Pill tone="amber">unreachable</Pill>
                    ) : n.severity === "OK" ? (
                      <Pill tone="green">ok</Pill>
                    ) : (
                      <Pill tone={n.severity === "CRITICAL" ? "red" : "amber"}>{n.severity.toLowerCase()}</Pill>
                    )}
                  </span>
                </div>
                <div className="grid gap-1.5">
                  {n.dims.map((d) => (
                    <div key={d.dimension} className="grid grid-cols-[4.5rem_1fr_3rem] items-center gap-2 text-[11.5px]" title={d.detail}>
                      <span style={{ color: "var(--adm-muted)" }}>{d.dimension.toLowerCase()}</span>
                      <Meter pct={d.pct} warnAt={data!.thresholds.warnPct} alertAt={data!.thresholds.critPct} label={`${n.name} ${d.dimension}`} />
                      <span className="text-right tabular-nums" style={{ color: "var(--adm-ink-2)" }}>{Math.round(d.pct)}%</span>
                    </div>
                  ))}
                </div>
              </li>
            ))}
        </ul>
      )}
    </Panel>
  );
}

async function ActivityPanel() {
  const recent = await db.auditLog
    .findMany({ include: { user: { select: { email: true } } }, orderBy: { createdAt: "desc" }, take: 9 })
    .catch(() => []);
  // Resolve the real admin behind any row taken while impersonating, so the feed
  // never shows a customer as the actor for something an admin did as them.
  const actorIds = [...new Set(recent.map((a) => actingAdminId(a.detail)).filter(Boolean))] as string[];
  const actorEmail = new Map(
    (actorIds.length ? await db.user.findMany({ where: { id: { in: actorIds } }, select: { id: true, email: true } }) : []).map(
      (u) => [u.id, u.email],
    ),
  );
  return (
    <Panel title="Activity" action={{ href: "/admin/audit", label: "Audit log" }}>
      {recent.length === 0 ? (
        <EmptyRow>No activity yet.</EmptyRow>
      ) : (
        <ul className="adm-list">
          {recent.map((a) => {
            const asAdmin = actingAdminId(a.detail);
            return (
              <li key={a.id} className="flex items-baseline gap-3 px-5 py-2.5 text-[13px]">
                <div className="min-w-0 flex-1">
                  <span className="font-medium" style={{ color: "var(--adm-ink)" }}>{a.action}</span>
                  <span className="ml-2 truncate text-[11.5px]" style={{ color: "var(--adm-faint)" }}>
                    {asAdmin ? (actorEmail.get(asAdmin) ?? asAdmin) : (a.user?.email ?? "system")}
                  </span>
                  {asAdmin && <span className="ml-2"><Pill tone="amber">as {a.user?.email ?? "customer"}</Pill></span>}
                </div>
                <span className="shrink-0 text-[11.5px]" style={{ color: "var(--adm-faint)" }}>{timeAgo(a.createdAt)}</span>
              </li>
            );
          })}
        </ul>
      )}
    </Panel>
  );
}

