import re,json
A1='/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/a1/'
old=open(A1+'old-groups.ts').read()
new=open('/opt/nxeon-wt-adminshell/lib/admin-nav.ts').read()
# old: section label -> entry label -> tabs
oldloc={}
sec=None; ent=None
for line in old.splitlines():
    m=re.search(r'key: "([^"]+)",\s*$',line)
    l=re.search(r'^\s{4}label: "([^"]+)"',line)
    if l: sec=l.group(1)
    e=re.search(r'^\s{8}label: "([^"]+)"',line)
    if e: ent=e.group(1)
    t=re.search(r'\{ label: "([^"]+)", href: "([^"]+)" \}',line)
    if t: oldloc.setdefault(t.group(2), f"{sec or 'Overview'} › {ent} › {t.group(1)}")
# new: parse groups/items/children
newloc={}; flags={}
grp=None; item=None
for line in new.splitlines():
    g=re.search(r'^\s{4}label: "([^"]+)",',line)
    if re.search(r'^\s{4}key: "command"',line): grp='Command center'
    if g: grp=g.group(1)
    it=re.search(r'^\s{6}\{ key: "[^"]+", label: "([^"]+)", href: "([^"]+)"(.*)\}',line)
    if it:
        item=it.group(1); newloc[it.group(2)]=f"{grp} › {item}"; flags[it.group(2)]=it.group(3)
        continue
    it2=re.search(r'^\s{8}label: "([^"]+)",',line)
    if it2: item=it2.group(1)
    h=re.search(r'^\s{8}href: "([^"]+)",',line)
    if h: newloc.setdefault(h.group(1), f"{grp} › {item}")
    rest=re.search(r'^\s{8}(more|pending|flag): ',line)
    if rest and h is None: pass
    c=re.search(r'^\s{10}\{ label: "([^"]+)", href: "([^"]+)"(.*)\}',line)
    if c: newloc[c.group(2)]=f"{grp} › {item} › {c.group(1)}"; flags[c.group(2)]=c.group(3)
# item-level more/pending/flag lines
cur=None
for line in new.splitlines():
    h=re.search(r'^\s{8}href: "([^"]+)",',line)
    if h: cur=h.group(1)
    for k in ('more: true','pending: "','flag: "'):
        if re.search(r'^\s{8}'+re.escape(k),line) and cur: flags[cur]=flags.get(cur,'')+' '+line.strip()
visits={}
for l in open(A1+'visits.txt'):
    p=[x.strip() for x in l.split('|')]
    if len(p)>=4: visits[p[0]]=(int(p[1]),p[3])
gates=dict(l.strip().split('|',1) for l in open(A1+'gates.txt'))
routes=[l.strip() for l in open(A1+'routes.txt')]
def norm(r): return re.sub(r'\[[^\]]+\]','[id]',r)
rows=[]
for r in routes:
    n=norm(r); v=visits.get(n,(0,'—'))
    gate=gates.get(r,'')
    gate=re.sub(r'requireArea(OrGrant)?\("([a-zA-Z]+)"\)',r'\2',gate).replace('hasAnyAreaAccess','any')
    o=oldloc.get(r,'—'); nl=newloc.get(r,'')
    f=flags.get(r,'')
    if '[' in r or r.endswith('/new'):
        parent=r.rsplit('/',1)[0]; nl=nl or (newloc.get(parent,'')+' › detail' if parent in newloc else ''); o=o if o!='—' else 'detail page'
        dec='keep (detail)'
    elif r=='/admin/login': dec='keep (public)'; nl='— (no shell)'
    elif 'pending' in f: dec='pre-registered'
    elif 'flag' in f: dec='demote to More (flag-gated)'
    elif 'more: true' in f: dec='demote to More'
    elif not nl: dec='unlisted (kept)'
    elif o=='—': dec='add to nav'
    else:
        og=o.split(' › ')[0]; ng=nl.split(' › ')[0]
        dec='keep' if og==ng or (og in ('Revenue',) and ng=='Billing') else 'move'
        if og=='Revenue' and ng=='Billing': dec='keep (group renamed)'
        if og=='Platform' and ng=='System': dec='keep (group renamed)'
        if og=='Overview' and ng!='Command center': dec='move'
    rows.append((r,o,nl or '—',gate or '—',v[0],v[1],dec))
print('| Route | Before (sidebar › entry › tab) | After (group › item › child) | Page gate | Views | Last view | Decision |')
print('|---|---|---|---|--:|---|---|')
for r in rows: print('| `%s` | %s | %s | %s | %d | %s | %s |'%r)
# pending ones not in routes
for h,f in flags.items():
    if 'pending' in f and h not in routes:
        print('| `%s` | — (new, other branch) | %s | — | — | — | pre-registered (%s) |'%(h,newloc.get(h,''),re.search(r'pending: "([^"]+)"',f).group(1)))
EOF
